int unique_element(int arr[], int size){
    int ans = 0;
    for(int i = 0; i<size; i++){
       //We used XOR operator (" ^ ") because a ^ a = 0. Hence, duplicate elements in array
       // will be deleted and unique element of array will be printed whose duplicate
       //is absent in array.
        ans = ans ^ arr[i];
    }
    return ans;
}
