//Coz array is containing numbers from 1 to n-1 and one duplicate_number also.
//i.e 1,2,3,4,......x....., n-1, x.         We have to find the duplicate_number
// which is " x ".

    //if we XOR the given array [1,2,3,4,.....x....., n-1, x] with the numbers
    //from 1 to n-1 [1,2,3,4,......,x,....n-1]
    //The output will be only " x ". Hence, The duplicate_number will be printed.
#include <iostream>
using namespace std;
int duplicate_number(int arr[], int size){
    int ans = 0;
    //XOR'ing the given array [1,2,3,4,.....x....., n-1, x] which gives only
    // ans = [1,2,3,4,.........., n-1]
    for(int i = 0; i<size; i++){
        ans = ans ^ arr[i];
    }
    //XOR'ing the previous ans = [1,2,3,4,.........., n-1] with numbers from 1 to n-1
    //i.e. [1,2,3,4,...,x,......., n-1]
    //Hence the duplicate_number which is " x " will be printed.
    for(int i = 0; i<size; i++){
        ans = ans ^ i;
    }
    return ans;
}
int main()
{
   int arr[10] = {1,2,3,4,3};
   cout<<duplicate_number(arr,5);
    return 0;
}

