#include <iostream>
using namespace std;
int binarySearch(int arr[], int size, int key){
    int start = 0;
    int end = size - 1;
    int mid = (start + end)/2;
    while(start <= end){
        if(key == arr[mid]){
            return mid;
        }
        if(key > arr[mid]){	//searching in right part of array.
            start = mid + 1;
        }
        else{	//searching in left part of array.
            end = mid - 1;
        }
        mid = (start + end)/2;
    }
    return -1;
}

{
    int even[4] = {10, 20, 30, 40};
    int odd[5] = {10, 20, 30, 40, 50};
    int key_index = binarySearch(even, 4, 30);
    cout<<"Index of 30 is "<< key_index<<endl;
    key_index = binarySearch(odd, 5, 50);
    cout<<"Index of 50 is "<< key_index<<endl;
    return 0;
}

