bool isPossible(vector<int> stall, int total_cows, int assumed_distance_for_cow) {
    int cow_count = 1;
    int cow1 = stall[0];
    for(int i=0; i < stall.size(); i++) {
        int cow2 = stall[i];
        int curr_distance = cow2 - cow1;
        // if first two cows don't fight, then next cow can be placed here
        if(curr_distance >= assumed_distance_for_cow) {
            cow_count++;
            if(cow_count == total_cows)     return true;
            // if more cows are left, then check for next two cows.
            // i.e. prevCow will become currCow and search for second one again.
            else
                cow1 = stall[i];
        }
    }
    return false;
}
