    void moveZeroes(vector<int>& nums) {
        int i=0;
        for(int j=0; j<nums.size(); j++){
            if(nums[j] != 0){   //If we get non zero then swap, else ignore zero
                swap(nums[i], nums[j]);
                i++;
            }
        }
    }
};

