To find the power of a number there are two cases i.end



1. if the number is power in even. e.g   2^4 = {(2^2)*(2^2)}

2. if the number in powe is odd. e.g.    2^5 = {2 * (2^2)*(2^2)}



In this approach, Number of iterations are decreased.

*/





int power(int a, int b){

    //Base case

    if(b == 0){

        return 1;

    }

    if(b == 1){

        return a;

    }



    //Recursive call

    int ans = power(a,b/2);



    if(b%2 == 0){   //If the number in power even

        return ans * ans;

    }

    else{

        return a * ans * ans;

    }

}



int main()

{

    int a = 2, b = 3;



    int ans = power(a,b);



    cout << "Final answer is " << ans << endl;



    return 0;

}

