#include <iostream>
using namespace std;
void merge(int *arr, int start, int end){
    int mid = (start + end)/2;
    int len1 = mid - start + 1;
    int len2 = end - mid;
    int *first = new int[len1];
    int *second = new int[len2];
    //copy values
    int k = start;
    for(int i = 0; i< len1; i++){
        first[i] = arr[k++];
    }
    k = mid + 1;
    for(int i = 0 ;i<len2 ; i++){
        second[i] = arr[k++];
    }
    //merging two sorted arrays
    int i = 0;
    int j = 0;
    k = start;
    while(i<len1 && j<len2){
        if(first[i] < second[j]){
            arr[k++] = first[i++];
        }
        else{
            arr[k++] = second[j++];
        }
    }
    //if some elements are left in first array
    while(i<len1){
      arr[k++] = first[i++];
    }
    //if some elements are left in second array
    while(j<len1){
      arr[k++] = second[j++];
    }
    delete []first;
    delete []second;
}
void mergeSort(int *arr, int start, int end){
    //base case
    if(start >= end){
        return;
    }
    int mid = (start + end)/2;
    //sorting left part of array
    mergeSort(arr, start, mid);
    //sorting right part of array
    mergeSort(arr, mid+1, end);
    //merging two arrays
    merge(arr, start, end);
}
void print(int *arr, int size){
    for(int i = 0; i< size; i++){
        cout << arr[i] << " ";
    }
    cout << endl;
}
int main() {
    int arr[7] = { 7,5,8,3,2,1,10};
    int size = 7;
    int start = 0 ;
    int end = size - 1;
    print(arr, size);
    mergeSort(arr,start, end);
    print(arr, size);
    return 0;
}

