class Solution {
public:
    vector<string> getSubSequences(string s, int index, vector<string> final, string ans, string digits){
        // Base case
        if(index == s.length() && ans.length() == digits.length()){
            final.push_back(ans);
            return final;
        }
        // Include.
        getSubSequences(s, index+1, final, ans + s[index], digits);
        // Exclude
        getSubSequences(s, index + 1, final, ans, digits);
        return final;
    }
    vector<string> letterCombinations(string digits) {
        unordered_map<int, string> mp;
        mp[2] = "abc";
        mp[3] = "def";
        mp[4] = "ghi";
        mp[5] = "jkl";
        mp[6] = "mno";
        mp[7] = "pqrs";
        mp[8] = "tuv";
        mp[9] = "wxyz";
        vector<string> ans;
        for(int i=0; i<digits.length(); i++){
            int num = digits[i] - '0';
            vector<string> vect;
            string output = "";
            vect = getSubSequences(mp[num], 0, vect, output, digits);
            // Copy resultant values of subs in ans.
            int j=0;
            while(j < vect.size()){
                ans.push_back(vect[j]);
            }
        }
        return ans;
    }
};

class Solution {
public:
    void solve(string digits, int index, string ans, vector<string> &final, vector<string> mapping){
        // Base case
        if(index >= digits.length()){
            final.push_back(ans);
            return;
        }
        int number = digits[index] - '0';
        string value = mapping[number];
        for(int i=0; i<value.length(); i++){
            // Including current character to ans.
            ans.push_back(value[i]);
            solve(digits, index+1, ans, final, mapping);
            // Make sure to empty ans string while returning to reuse it.
            ans.pop_back();
        }
    }
    vector<string> letterCombinations(string digits) {
        // Base case
        if(digits.length() == 0)
            return {};
        vector<string> final;
        string ans = "";
        int index = 0;
        // It's an array but consider it as a Map.
        vector<string> mapping = {" ", " ", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
        solve(digits, index, ans, final, mapping);
        return final;
    }
};

