void deleteNode_by_value(int dataToDelete, Node *&head, Node * &tail){



    Node *previous = NULL;

    Node *current = head;







    //Reaching to the element by linear search.

    while(dataToDelete != current -> data){

        previous = current;

        current = current -> next;

    }



    if(current == head){        //If the element is at first position.

        head = head -> next;

        current -> next = NULL;



        delete current;

    }

    else{

        previous -> next = current -> next;

        current -> next = NULL;



        //updating the tail

        if(previous -> next == NULL){

            tail = previous;

        }



        //memory free

        delete current;

    }

}

