Node* kReverse(Node* head, int k) {
    //base case
	if(head == NULL){
		return NULL;
	}
	Node* prev = NULL;
	Node* curr = head;
	Node* forward = NULL;
	int count = 0;
	//Using iterative approach as done in previous lecture no.45
	//step 1: reverse first K nodes
	while(curr != NULL && count < k){
		forward = curr -> next;
		curr -> next = prev;
		prev = curr;
		curr = forward;
		count++;
	}
	//step 2: Recursive call
	if(forward != NULL){
		head -> next = kReverse(forward, k);
	}
	//step 3: Return the head of reversed Linked List
	return prev;
}

