class Solution{
  private:
    Node* getMid(Node* head){
        Node* slow = head;
        Node* fast = head -> next;
        while((fast != NULL) && (fast -> next != NULL)){
            slow = slow -> next;
            fast = fast -> next -> next;
        }
        return slow;    //slow will be pointing to Middle of LL.
    }
    Node* reverse(Node* head){
        //If list is empty or have only one node.
        if(head == NULL || head -> next == NULL){
    		return head;
    	}
    	Node* prev = NULL;
    	Node* curr = head;
    	Node* forward = NULL;
    	while(curr != NULL){
    		forward = curr -> next;
    		curr -> next = prev;
    		prev = curr;
    		curr = forward;
    	}
    	return prev;
    }
  public:
    //Function to check whether the list is palindrome.
    bool isPalindrome(Node *head)
    {
        if(head == NULL || head -> next == NULL){
            return true;
        }
        //Step 1-- Find Middle
        Node* middle = getMid(head);
        //Step 2-- Reverse LL after middle.
        Node* temp = middle -> next;
        middle -> next = reverse(temp);
        //Step 3-- Compare both halves
        Node *head1 = head;
        Node *head2 = middle -> next;
        while(head2 != NULL){
            //if data is not equal means not palindrome
            if(head1 -> data != head2 -> data){
                return false;
            }
            else{ //data is equal means palindrome
                head1 = head1 -> next;
                head2 = head2 -> next;
            }
        }
        //Step 4-- Repeat step 2, so that we can have same LL as initial
        //Node* temp = middle -> next;
        middle -> next = reverse(temp);
        return true;
    }
};

