class Solution
{
    private:
    Node* reverse(Node* head) {
        Node* curr = head;
        Node* prev = NULL;
        Node* next = NULL;
        while(curr != NULL) {
            next = curr -> next;
            curr -> next = prev;
            prev = curr;
            curr = next;
        }
        return prev;
    }
    void insertAtTail(struct Node* &head, struct Node* &tail, int val) {
        Node* temp = new Node(val);
        //empty list
        if(head == NULL) {
            head = temp;
            tail = temp;
            return;
        }
        else
        {
            tail -> next = temp;
            tail = temp;
        }
    }
    struct Node* add(struct Node* first, struct Node* second) {
        int carry = 0;
        Node* ansHead = NULL;
        Node* ansTail = NULL;
        //IF BOTH OF THE LINKED LISTS ARE NON NULL
        while(first != NULL && second != NULL) {
            int sum = carry + first -> data + second -> data;   //adding two numbers
            int digit = sum % 10;   //extracting right digit to insert in answer node
            //creating Node and inserting in answer Linked list
            insertAtTail(ansHead, ansTail, digit);
            carry = sum / 10;     //extracting carry to add in next number.
            //updating pointers
            first  = first -> next;
            second = second -> next;
        }
        //IF SECOND LINKED LIST REACHED NULL
        while(first != NULL){
            int sum = carry + first -> data;
            int digit = sum % 10;
            insertAtTail(ansHead, ansTail, digit);
            carry = sum / 10;
            first = first -> next;
        }
        //IF FIRST LINKED LIST REACHED NULL
        while(second != NULL){
            int sum = carry + second -> data;
            int digit = sum % 10;
            insertAtTail(ansHead, ansTail, digit);
            carry = sum / 10;
            second = second -> next;
        }
        //IF CARRY IS LEFT AFTER ADDING LLAST NODE OF LINKED LIST
        while(carry != 0){
            int sum = carry;
            int digit = sum % 10;
            insertAtTail(ansHead, ansTail, digit);
            carry = sum / 10;
        }
        return ansHead;
    }
    public:
    //Function to add two numbers represented by linked list.
    struct Node* addTwoLists(struct Node* first, struct Node* second)
    {
        //step 1 -  reverse input LL
        first = reverse(first);
        second = reverse(second);
        //step2 - add 2 LL
        Node* ans = add(first, second);
        //step 3 -- reverse answer LL
        ans = reverse(ans);
        return ans;
    }
};

