//Merge sort a Linked List



//Before solving this question, revise merge sort in array lec 35



//STEPS TO SOLVE PROBLEM



//STEP 1 —   Base case

//STEP 2 —  Break Linked list into two halves after finding mid.

//STEP 3 — Recursive calls to sort both halves

//STEP 4 — Merge both left and right halves of linked list







//finding Mid by Floyd's Algorithm or Hare and tortoise algo

node* findMid(node* head){

	node* slow = head;

	node* fast = head -> next;



	while(fast != NULL && fast -> next != NULL){

		slow = slow -> next;

		fast = fast -> next -> next;

	}

	return slow;

}



node* merge(node* left, node* right){

	//base cases or if there is no element in linked list

	if(left == NULL){

		return right;

	}

	if(right == NULL){

		return left;

	}



	node* ans = new node(-1);

	node* temp = ans;



	while(left != NULL && right != NULL){

		if(left -> data < right -> data){

			temp -> next = left;

			temp = left;

			left = left -> next;

		}

		else{

			temp -> next = right;

			temp = right;

			right = right -> next;

		}

	}



	//If some elements of first are left

	while(left != NULL){

		temp -> next = left;

		temp = left;

		left = left -> next;

	}



	//If some elements of second are left

	while(right != NULL){

		temp -> next = right;

		temp = right;

		right = right -> next;

	}



	//we did this because ans was at dummy node i.e. -1.

	//to get perfect LL, we moved next to that dummy Node.

	ans = ans -> next;



	return ans;

}



node* mergeSort(node *head) {

    //base case

	if(head == NULL || head -> next == NULL){	//if there is only one node or no node

		return head;

	}



	//Break Linked list into two halves after finding mid.

	node* mid = findMid(head);



	node* left = head;

	node* right = mid -> next;



	// So that the last element of first half can be NULL

	mid -> next = NULL;



	//Recursive calls to sort both halves

	left = mergeSort(left);

	right= mergeSort(right);



	//merge both left and right halves of linked list

	node* result = merge(left, right);



	return result;

}

