        //step 3: Single element in stack is potential celebrity
        //Verify that element
        //row should be 0 for all i.e.  celebrity knows no one
        //col should be 1 for all except diagonal i.e everyone knows celebrity
        //Row check
        bool rowCheck = false;
        int zeroCount = 0;
        for(int i=0; i<n; i++){
            if(M[ans][i] == 0){
