        // int n = heights.size();
        vector<int> next(n);
        next = nextSmallerElement(heights,n);
        vector<int> prev(n);
        prev = prevSmallerElement(heights,n);
        int area = INT_MIN;
        for(int i = 0; i<n; i++){
            int l = heights[i];
            //Means if all elements are same (no smaller value in array)
            if(next[i] == -1){
                next[i] = n;
            }
            int b = next[i] - prev[i] - 1;
            int newArea = l*b;
            area = max(area, newArea);
        }
        return area;
    }
  public:
    int maxArea(int M[MAX][MAX], int n, int m) {
        //compute area for first row.
        int area = largestRectangleArea(M[0], m);
        for(int i=0; i<n; i++){
            for(int j=i+1; j<n; j++){
                //row update by adding previous row's value
                if(M[i][j] != 0){
                    M[i][j] = M[i][j] + M[i-1][j];
                }
                else{
                    M[i][j] = 0;
                }
            }
