#include <iostream>
using namespace std;
class Node{
    public:
        int data;
        Node *next;
    Node(int new_data){
        this -> data = new_data;
        next = NULL;
    }
};
class queue{
    public:
        Node *front;
        Node * rear;
    queue(){
        front = NULL;
        rear = NULL;
    }
    void enqueue(int data){
        Node *nodeToInsert = new Node(data);
        if(front == NULL){      //Single node linked list
            front = nodeToInsert;
            rear = nodeToInsert;
            rear -> next = NULL;
        }
        else{       //More than one node linked list
            rear -> next = nodeToInsert;
            rear = nodeToInsert;
        }
    }
    void dequeue(){
        //empty linked list
        if(front == NULL){
            cout << "Stack Underflow" << endl;
            return;
        }
        else{       //Non empty linked list
            Node *nodeToDelete = front;
            int ans = nodeToDelete -> data;
            front = front -> next;
            if(front == NULL){
                rear = NULL;
            }
            delete nodeToDelete;
            cout << " Node is deleted which had value " << ans << endl;
        }
    }
    int size(Node *front){
        Node *temp = front;
        int count = 0;
        while(temp != NULL){
            temp = temp -> next;
            count++;
        }
        return count;
    }
};
int main(){
    queue q;
    q.enqueue(10);
    q.enqueue(20);
    q.dequeue();
    q.dequeue();
    q.dequeue();
    return 0;
}

