class CircularQueue{
    public:
    int size;
    int *arr;
    int front;
    int rear;
    int currSize = 0;
    CircularQueue(int n){
        size = n;
        arr = new int[size];
        front = -1;
        rear = -1;
    }
    // Enqueues 'X' into the queue. Returns true if it gets pushed into the stack, and false otherwise.
    bool enqueue(int value){
        //to check whether queue is full
        if(currSize == size){
            cout << "Queue is full " << endl;
            return false;
        }
        else if(front == -1){    //first element to push
            front = rear = 0;
        }
        else if(rear == size - 1 && front != 0){    //to maintain the cyclic nature.
            rear = 0;
        }
        else{    //Normal flow
            rear++;
        }
        arr[rear] = value;
        currSize++;
        return true;
    }
    // Dequeues top element from queue. Returns -1 if the stack is empty, otherwise returns the popped element.
    int dequeue(){
        if(front == -1){    //to check if queue is empty
            //cout << "Queue is empty " << endl;
            return -1;
        }
        //storing the value of front to return.
        int ans = arr[front];
        arr[front] = -1;
        if(front == rear){    //single element is present
            front = rear = -1;
        }
        else if(front == size -1){    //to maintain the cyclic nature.
            front = 0;
        }
        else{    //Normal flow
            front++;
        }
        currSize--;
        return ans;
    }
    int getFront() {
        if(front >= 0) return arr[front];
        return -1;
    }
};
int main() {
    CircularQueue q(10);
    bool temp = q.enqueue(21000);
    cout << "front is " << q.getFront() << endl;
    return 0;
}

