    int qRear;
    int size;
    int capacity;
    MyCircularQueue(int k) {
        size = k;
        arr = new int[size];
        qFront = 0;
        qRear = -1;
        capacity = 0;
    }
    bool enQueue(int value) {
        if(capacity == size)
