#include <iostream>
#include <queue>
#include <stack>
#include <algorithm>
using namespace std;
class Node{
    public:
        int data;
        Node *left;
        Node *right;
    Node(int d){
        this -> data = d;
        this -> left = NULL;
        this -> right = NULL;
    }
};

if(data == -1){
    return NULL;
}

void inOrder(Node *root){
    //creating an empty stack.
    stack<Node*> stack;
    Node *curr = root;
    while(curr != NULL || !stack.empty()){
        if(curr != NULL){
            stack.push(curr);
            curr = curr -> left;    //Going to the left of root.
        }
        else{
            curr = stack.top();
            stack.pop();
            cout << curr -> data << " ";
            curr = curr -> right;
        }
    }
}

void preOrder(Node *root){
    //Return is Tree is empty
    if(root == NULL){
        return;
    }
    stack<Node*> stack;
    stack.push(root);
    while(!stack.empty()){
        Node *curr = stack.top();
        stack.pop();
        cout << curr -> data << " ";
        if(curr -> right){      //Push right first, coz of LIFO rule
            stack.push(curr->right);
        }
        if(curr -> left){
            stack.push(curr->left);
        }
    }
}

class Solution {
public:
    vector<int> postorderTraversal(Node* root) {
        // Base case
        if(root == NULL)
            return {};
        stack < Node* > s1;
        stack < Node* > s2;
        vector<int> ans;
        s1.push(root);
        while(!s1.empty()){
            root = s1.top();
            s1.pop();
            if(root -> left != NULL){
                s1.push(root -> left);
            }
            if(root -> right != NULL){
                s1.push(root -> right);
            }
            s2.push(root);
        }
        while(!s2.empty()){
            ans.push_back(s2.top() -> data);
            s2.pop();
        }
        return ans;
    }
};

void levelOrderTraversal(Node *root){
    queue <Node* > q;
    q.push(root);
    while (!q.empty())
    {
        Node* curr = q.front();
        cout << curr -> data << " ";
        q.pop();
        if(curr -> left)
            q.push(curr -> left);
        if(curr -> right)
            q.push(curr -> right);
    }
}
int main() {
    Node *root = NULL;
    //Creating a Tree.
    //1 3 7 -1 -1 11 -1 -1 5 17 -1 -1 -1
    root = buildTree(root);
    cout << endl << endl;
    cout << "In Order Traversal : ";
    inOrder(root);
    cout << endl << endl;
    cout << "Pre Order Traversal : ";
    preOrder(root);
    cout << endl << endl;
    cout << "Post Order Traversal : ";
    //postOrder(root);
    cout << endl << endl;
    cout << "Level Order Traversal : ";
    levelOrderTraversal(root);
    //cout << "Level Order Traversal : " << endl;
    // levelOrderTraversal(root);
    return 0;
