class Solution
{
    public:
    //Function to return a list of nodes visible from the top view
    //from left to right in Binary Tree.
    /* Basically, just like vertical order traversal, we will make 1:1 entry for every distance
    No, need to make double entry coz rest of Nodes will be hidden behind these entries if we look
     from top of the tree.	*/
    vector<int> topView(Node *root)
    {
        // Base case
        if(!root)   return {};
        vector<int> ans;
        map<int, int> topNode;      // distance,  root->val
        queue<pair<Node*, int>> q;  // root,      distance.
        q.push(make_pair(root, 0));            // coz, Horizontal distance is always zero initially
        while(!q.empty())
        {
            pair<Node*, int> temp = q.front();
            q.pop();
            Node* frontNode = temp.first;
            int dist      = temp.second;
            // If we find the entry of distance in map then do nothing.
            // Otherwise
            // 1:1 Entry only
            if(topNode.find(dist) == topNode.end())
            {
                topNode[dist] = frontNode->data;
            }
            if(frontNode->left)     q.push(make_pair(frontNode->left, dist-1));
            if(frontNode->right)    q.push(make_pair(frontNode->right, dist+1));
        }
        for(auto i: topNode)
        {
            ans.push_back(i.second);
        }
        return ans;
    }
};

