class Solution{
  public:
    pair<int,int> solve(Node* root) {
        // base case
        if(!root)   return {0,0};
        pair<int,int> left = solve(root->left);
        pair<int,int> right = solve(root->right);
        pair<int,int> result;
        // INCLUDE ROOT
        // root->data + excluded part of left + excluded part of right
        result.first = root->data + left.second + right.second;
        // EXCLUDE ROOT
        // max(include_left, exclude_left) + max(include_right, include_right);
        result.second = max(left.first, left.second) + max(right.first, right.second);
        return result;
    }
    int getMaxSum(Node *root)
    {
        // < include current, exclude current but take max of left pair + max of right pair>
        pair<int,int> ans =  solve(root);
        return max(ans.first, ans.second);
    }
};

