class Solution {
public:
    int widthOfBinaryTree(TreeNode* root) {
        int ans = 0;
        queue<pair<TreeNode*, long long int>> q;
        q.push({root, 0});
        while(q.size())
        {
            int len = q.size();
            int leftMost, rightMost;
            int minAtLevel = q.front().second;          // Minimum is first entry's index
            for(int i = 0; i < len; i++)
            {
                auto it = q.front();
                TreeNode* curr = it.first;
                int idx = it.second - minAtLevel;       // To avoid overflow, subtract idx - minimumAtlevel
                q.pop();
                if(i == 0)        leftMost = idx;
                if(i == len-1)    rightMost = idx;
                if(curr->left)  q.push({curr->left, 2LL * idx+1});          // leftChild
                if(curr->right) q.push({curr->right, 2LL * idx+2});         // rightChild
            }
            ans = max(ans, rightMost-leftMost+1);
        }
        return ans;
    }
};

