class Solution {
public:
    int find_root_position(int element, vector<int> &inOrder)
    {
        for(int i = 0; i < inOrder.size(); i++) {
            if(inOrder[i] == element)
                return i;
        }
        return -1;
    }
    int preOrder_idx = 0;
    TreeNode* build(int inOrder_start, int inOrder_end,
                    vector<int> &preOrder, vector<int> &inOrder) {
        // Base case
        if(preOrder_idx >= preOrder.size()) return NULL;
        if(inOrder_start > inOrder_end)     return NULL;
        // Step 1: Make root from preOrder[current]
        int node = preOrder[preOrder_idx];
        preOrder_idx++;
        TreeNode* root = new TreeNode(node);
        // Step 2: Find position of same element from InOrder
        // This complexity of repeatitive function call can be optimised
        // by using mapping of nodes with their index.
        int root_position = find_root_position(node, inOrder);
        // Step 3: Do Same for Left and Right child but with compressed indexes/searchSpace
        root->left = build(inOrder_start, root_position-1, preOrder, inOrder);
        root->right= build(root_position + 1, inOrder_end, preOrder, inOrder);
        return root;
    }
    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        int inOrder_start = 0;
        int inOrder_end = inorder.size()-1;
        return build(inOrder_start, inOrder_end, preorder, inorder);
    }
};

class Solution {
public:
    int find_root_position(int element, vector<int> &inOrder) {
        for(int i = 0; i < inOrder.size(); i++) {
            if(inOrder[i] == element)
                return i;
        }
        return -1;
    }
    int postOrder_idx;
    TreeNode* build(int inOrder_start, int inOrder_end, vector<int> &inOrder, vector<int> &postOrder)
    {
        if(postOrder_idx < 0)           return NULL;
        if(inOrder_start > inOrder_end) return NULL;
        // Step 1: Make postOrder[current] Root of the tree
        int node = postOrder[postOrder_idx];
        postOrder_idx--;
        TreeNode* root = new TreeNode(node);
        // Step 2: Get the position of root from inOrder
        int root_position = find_root_position(node, inOrder);
        // Step 3: Recursive calls from Right, then left with compressed searchSpace
        // Coz jis Order ch apna index chl reha ohi part pehlan build krna.
        // that's why we have created Right Part of Tree first
        root->right = build(root_position + 1, inOrder_end, inOrder, postOrder);
        root->left  = build(inOrder_start, root_position - 1, inOrder, postOrder);
        return root;
    }
    TreeNode* buildTree(vector<int>& inorder, vector<int>& postorder) {
        int n = postorder.size();
        postOrder_idx = n-1;
        int inOrder_start = 0, inOrder_end = n-1;
        return build(inOrder_start, inOrder_end, inorder, postorder);
    }
};

