class Solution {
  public:
    // This function creates Node to parent mapping using level
    // order traversal and return Target Node
    unordered_map<Node*, Node*> nodeToParent;
    Node* createMapping(int target, Node* root) {
        Node* result = NULL;
        queue<Node*> q;
        q.push(root);
        while(q.size()) {
            Node* curr = q.front();
            q.pop();
            if(curr->data == target)    result = curr;
            // Create Mapping
            if(curr->left) {
                nodeToParent[curr->left] = curr;    // curr->left's parent is curr
                q.push(curr->left);
            }
            if(curr->right) {
                nodeToParent[curr->right] = curr;   // curr->right's parent is curr
                q.push(curr->right);
            }
        }
        return result;
    }
    int maxTime_to_burn_tree(Node* target) {
        int res_time = 0;
        unordered_map<Node*, int> vis;
        queue<pair<Node*, int>> q;
        q.push({target, 0});
        vis[target] = 1;
        while(q.size()) {
            Node* curr = q.front().first;
            int time = q.front().second;
            q.pop();
            res_time = max(res_time, time);
            // Left Node
            if(curr->left && !vis[curr->left]) {
                q.push({curr->left, time+1});
                vis[curr->left] = 1;
            }
            // Right Node
            if(curr->right && !vis[curr->right]) {
                q.push({curr->right, time+1});
                vis[curr->right] = 1;
            }
            // Parent Node
            Node *parent = nodeToParent[curr];
            if(parent && !vis[parent]) {
                q.push({parent, time+1});
                vis[parent] = 1;
            }
        }
        return res_time;
    }
    int minTime(Node* root, int target)
    {
        // Step 1: Create Node to parent mapping for all node.
        Node* targetNode = createMapping(target, root);
        // Step 2: Call BFS just like graph and get Maximum time required to
        // burn all nodes of tree
        return maxTime_to_burn_tree(targetNode);
    }
};

class Solution {
  public:
