class Solution {
public:
    int getSum(TreeNode* root, int & res)
    {
        // Base case
        if(!root)   return 0;
        // Go to extreme left and extreme right & then start calculating
        // we are comparing with '0' coz if we encounter -ve number it will
        // ignore it and return 0 as maximum
        int leftSum = max(0, getSum(root->left, res));          // to neglect negative path sum
        int rightSum = max(0, getSum(root->right, res));        // we compared with 0
        // If we get result in umbrella shaped path then relation will be
        // maxSum = curr + leftSum + rightSum
       // Update our answer after every recursive call.
        res = max(res, leftSum + rightSum + root->val);         // final ans is building here
        // Just return this for currentNode, coz we can't return both
        // left and right path to above node. So return current + max of both path
        // to its parent.
        return root->val + max(leftSum,rightSum);   // answer for currNode in recursive call, not overall answer
    }
    int maxPathSum(TreeNode* root) {
        int res = INT_MIN;
        getSum(root, res);
        return res;
    }
};

