class Solution {
public:
    bool isValidBST(TreeNode* root) {
        return validate(root, std::numeric_limits<long>::min(), std::numeric_limits<long>::max() );
    }
private:
    bool validate(TreeNode* node, long lower, long upper){
        if( node == NULL ){
            // empty node or empty tree is valid always
            return true;
        }
        if( (lower < node->val) && (node->val < upper) ){
            // check if all tree nodes follow BST rule
            return validate(node->left, lower, node->val) &&
                    validate(node->right, node->val, upper);
        }
        else{
            // early reject when we find violation
            return false;
        }
    }
};

bool isBST(BinaryTreeNode <int>* root, int min, int max){
    //Base case
    if(root == NULL){
        return true;
    }
    //if it satisfies the conditions of BST
    if(root-> data >= min && root->data <= max){
        bool left = isBST(root->left, min, root-> data);    //Left check
        bool right = isBST(root->right, root->data , max);  //Right check
        return left && right;
    }
    else{
        return false;
    }
}
bool validateBST(BinaryTreeNode<int> *root) {
    return isBST(root, INT_MIN, INT_MAX);
}

