vector<int> buildMinHeap(vector<int> &arr)

{

    int n = arr.size();

    //For 0 Based Indexing

    // coz for 1-based index, N/2+1 to size Nodes are leaf nodes

    // and leaf Nodes are already heap itself, so no need to call for them.

    for(int i= n/2-1; i>=0; i--){

        heapify(arr, n , i);

    }

    return arr;

}

