class Solution{
    public:
    // arr : given array
    // l : starting index of the array i.e 0
    // r : ending index of the array i.e size-1
    // k : find kth smallest element and return using this function
    int kthSmallest(int arr[], int l, int r, int k) {
        priority_queue<int> pq;
        //Step 1: Make a heap for first K elements
        for(int i = 0; i<k; i++){
            pq.push(arr[i]);
        }
        //Step 2: Processing with the rest of elements from K to Last and compare Heap's elements
        //Compare the rest of elments with heaps element.
        //If you find smaller than arr[i] in heap then pop it and push to array.
        //After entire iteration, top() of heap will be your answer.
        for(int i=k; i<=r; i++){    //We used <=r coz r is index but not the number of element.
            if(arr[i] < pq.top()){
                pq.pop();
                pq.push(arr[i]);
            }
        }
        int ans = pq.top();
        return ans;
    }
};

