class Solution {
  public:
int countNodes(struct Node* root){
      int count;
      //Base case
      if(root == NULL){
          return 0;
      }
      count = 1 + countNodes(root -> left) + countNodes(root -> right);
      return count;
  }
  bool isCBT(struct Node *root, int i, int count){
      //Base case
      if(root == NULL){
          return true;
      }
      //If index of Node exceeds Node count then means somewhere insertion is from
      // right and left part is skipped
      if(i >= count){   //coz we r using 0 Based Indexing
          return false;
      }
      else{
          bool left = isCBT(root-> left, 2*i + 1, count);
          bool right = isCBT(root->right, 2*i + 2, count);
          return (left && right);
      }
  }
  bool isMaxOrder(struct Node* root){
      // 0 child or Leaf Node
      if(root -> left == NULL && root -> right == NULL){
          return true;
      }
      //Only Left Node exists.
      if(root -> right == NULL){
          return (root->data > root->left->data);
      }
      else{     //Both Nodes or Left Node Exists
          bool left = isMaxOrder(root->left);   //Check for left
          bool right = isMaxOrder(root->right); //Check for right too.
          return (left && right &&
                    root->data > root->left->data && root->data > root->right->data);
      }
  }
    bool isHeap(struct Node* tree) {
        int index = 0;
        int count = countNodes(tree);
        if(isCBT(tree, index, count) && isMaxOrder(tree)){
            return true;
        }
        else{
            return false;
        }
    }
};

