    //Function to return the minimum cost of connecting the ropes.
    long long minCost(long long arr[], long long n) {
        //Step 1: Create a Min heap
        priority_queue<long long, vector<long long>, greater<long long> > minHeap;
        //Step 2: Push all elements of array into Min Heap
        for(int i=0; i<n; i++){
            minHeap.push(arr[i]);
        }
        long long cost = 0;
        while(minHeap.size() > 1){
            //Step 3: Take two smallest elements and add them into cost.
            long long a = minHeap.top();
            minHeap.pop();
            long long b = minHeap.top();
            minHeap.pop();
            long long sum = a + b;
            cost += sum;
            //Step 4: Again push sum to the Min Heap to get overall sum
            minHeap.push(sum);
        }
        return cost;
    }
};

