bool isSafeToMove(int newX, int newY, vector<vector<int>> & arr, int n, vector<vector<bool>> & vis){
    if((newX >= 0 && newX < n) &&
       (newY >= 0 && newY < n) &&
       arr[newX][newY] != 0 &&
       vis[newX][newY] != 1)
        return true;
    return false;
}
void solve(int x, int y, vector<vector<int>> &arr, int n, vector<string> & ans, vector<vector<bool>> & vis, string path){
    // Base case
    if(x == n-1 && y == n-1){
        ans.push_back(path);
        return ;
    }
    // Before Moving from specific block, Mark it visited
    vis[x][y] = 1;
    // 4 Movements    (row = x, col = y)
    // Down
    if(isSafeToMove(x+1, y, arr, n, vis)){
        solve(x+1, y, arr, n, ans, vis, path + 'D');
    }
    // Left
    if(isSafeToMove(x, y-1, arr, n, vis)){
        solve(x, y-1, arr, n, ans, vis, path + 'L');
    }
    // Right
    if(isSafeToMove(x, y+1, arr, n, vis))
        solve(x, y+1, arr, n, ans, vis, path + 'R');
    // Up
    if(isSafeToMove(x-1, y, arr, n, vis))
        solve(x-1, y, arr, n, ans, vis, path + 'U');
    // After Returning from every Function, Mark that block unvisited to check new Path.
    vis[x][y] = 0;
}
vector < string > searchMaze(vector < vector < int >> & arr, int n) {
    vector<string> ans;
    vector<vector<bool >> vis (n, vector<bool> (n, 0));
    string path = "";
    // Base case
    if(arr[0][0] == 0)
        return ans;
    int x = 0, y = 0;
    solve(x, y, arr, n, ans, vis, path);
    return ans;
}

