class Solution {
public:
    bool isSafe(int row, int col, char val, vector<vector<char>> board){
        for(int i = 0; i < board.size(); i++){
            // Row check -> row will remain same
            if(board[row][i] == val)
                return false;
            // Col Check -> Col will remain same
            if(board[i][col] == val)
                return false;
            // 3 * 3 Matrix check
            if(board[3*(row/3) + i/3][3*(col/3) + i%3] == val)
                return false;
        }
        return true;
    }
    bool solve(vector<vector<char>> & board){
        int n = board.size();
        for(int row = 0; row < n; row++){
            for(int col = 0; col < n; col++)
            {
                // If Empty cell
                if(board[row][col] == '.')
                {
                    for(char val = '1'; val <= '9'; val++){
                        // Value pa k check kro k valid h yan nhi
                        if(isSafe(row, col, val, board))
                        {
                            board[row][col] = val;
                            if(solve(board) == true)
                                return true;
                            board[row][col] = '.';      // Otherwise, Backtrack
                        }
                    }
                    return false;       // Solution not available for this row and col
                }
            }
        }
        return true;
    }
    void solveSudoku(vector<vector<char>>& board) {
        solve(board);
    }
};

