    for(auto neighbour: adj[node])
    {
        if(!visited[neighbour])
        {
            topoSort(neighbour, visited, s, adj);
        }
    }
    //If recursive call return for a Node, Push that node into stack
    s.push(node);
}
vector<int> topologicalSort(vector<vector<int>> &edges, int v, int e)  {
    // Create an Adjacency list
    unordered_map<int, list<int> > adj;
    for(int i=0; i<e; i++)
    {
        int u = edges[i][0];
        int v = edges[i][1];
        adj[u].push_back(v);
    }
    //Call Topological sort for all components.
    vector <bool> visited(v);
    stack<int> s;
    for(int i=0; i<v; i++)        //For every node
    {
        if(!visited[i])
        {
            topoSort(i, visited, s, adj);
        }
    }
    //Storing overall ans of stack in vector
    vector<int> ans;
    while(!s.empty())
    {
        ans.push_back(s.top());
        s.pop();
    }
    return ans;
}

