int detectCycleInDirectedGraph(int n, vector < pair < int, int >> & edges) {
    //Step 1: Create an adjacency list
    unordered_map<int, list<int> > adj;
    for(int i=0; i<edges.size(); i++){
        int u = edges[i].first - 1;        //coz nodes are from 1 but not from 0
        int v = edges[i].second - 1;
        adj[u].push_back(v);
    }
    //Step 2: Find all inDegrees
    vector<int> inDegree(n);
    for(auto i: adj){
        for(auto j: i.second){
            inDegree[j]++;
        }
    }
    //Step 3: Push the element having 0 inDegree in queue
    queue<int> q;
    for(int i=0; i<n; i++){        //coz nodes are from 1 but not from 0
        if(inDegree[i] == 0){
            q.push(i);
        }
    }
    //Step 4: Do BFS
    int count = 0;
    while(!q.empty()){
        int front = q.front();
        q.pop();
        //increment count
        count++;
        //neighbour inDegree update
        for(auto neighbour: adj[front]){
            inDegree[neighbour]--;
            if(inDegree[neighbour] == 0){
                q.push(neighbour);
            }
        }
    }
    /*
    if count == total number of nodes in graph,
    then it is valid Topo sort
    Means graph is acyclic
    else count != total number of nodes in graph
    then it is not valid Topo sort
    Means graph is cyclic
    */
    if(count == n){
        return false;    //cycle not present
    }
    else{
        return true;     //cycle is present
    }
}

