vector<int> shortestPath( vector<pair<int,int>> edges , int n , int m, int s , int t){
	//Step 1: Create an Adjacency List
    unordered_map<int, list<int> > adj;
    for(int i=0; i<edges.size(); i++){
        int u = edges[i].first;
        int v = edges[i].second;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    //Step 2: Do BFS
    unordered_map<int, bool> visited;
    unordered_map<int, int> parent;
    queue<int> q;
    q.push(s);        //'s' is source node.
    parent[s] = -1;
    visited[s] = true;
    while(!q.empty()){
        int front = q.front();
        q.pop();
        //Traverse for all neighbours
        for(auto i: adj[front]){
            if(!visited[i]){
                visited[i] = true;
                parent[i] = front;
                q.push(i);
            }
        }
    }
    //Step 3: Prepare shortest Path starting from last to first by backtracking
    vector<int> ans;
    int currentNode = t;    //'t' is destination node
    ans.push_back(t);
    while(currentNode != s){
        currentNode = parent[currentNode];
        ans.push_back(currentNode);
    }
    //Step 4: Reverse the ans i.e. Parent vala vector
    reverse(ans.begin(), ans.end());
    return ans;
}

