            for(auto j: i.second)
            {
                cout << "(" << j.first << "," << j.second << ")," ;
            }cout << endl;
        }
    }
    void dfs(int node, unordered_map<int, bool> &visited, stack<int> &topo)
    {
        visited[node] = 1;
        //Check for neighbours whether visited or not
        for(auto neighbour: adj[node])
        {
            if(!visited[neighbour.first])           //coz neighbour is pair and we want to acess first element
            {
                dfs(neighbour.first, visited, topo);
            }
        }
        topo.push(node);       //While returning from function, push node to stack that will be topo sort
    }
    void getShortestPath(int source, vector<int> &distance, stack<int> &topo)
    {
                                    //Step a: Make the distance of Source 0 to get into below if(  ) condition
        distance[source] = 0;
