            {
                for(auto i: adj[top])           //Step d: Traverse for other neighbours in Adjacency list
                {
                    if(distance[top] + i.second  <  distance[i.first])      //Step e: If distance[current or top] + to next element is less than distance[cuurent]
                    {
                        distance[i.first] = distance[top] + i.second;       //Step f: Update distance array.
                    }
                }
            }
        }
    }
};

