#include <set>
#include <limits.h>
vector<int> dijkstra(vector<vector<int>> &vec, int vertices, int edges, int source) {
    //Step 1: Create an Adjacency List
    unordered_map<int, list<pair<int,int> > > adj;
    for(int i=0; i<edges; i++){
        int u = vec[i][0];
        int v = vec[i][1];
        int weight = vec[i][2];        //Check list to understand it
        adj[u].push_back(make_pair(v,weight));
        adj[v].push_back(make_pair(u,weight));
    }
    //Step 2: Creation of Distance array with infinite values initially
    vector<int> distance(vertices);
    for(int i=0; i<vertices; i++){
        distance[i] = INT_MAX;
    }
    //Creation of Set on basis (Distance, Node)
    set<pair<int, int>> st;
    //Initialise distance and set with source node
    distance[source] = 0;
    st.insert(make_pair(0, source));
    while(!st.empty())
    {
        //step a: Fetch top record from set
        auto top = *(st.begin());
        int nodeDistance = top.first;
        int topNode = top.second;
        //step b: Remove the top record
        st.erase(st.begin());
        //step c: Traverse on neighbours from adjacency List
        for(auto neighbour: adj[topNode]){
            if(nodeDistance + neighbour.second < distance[neighbour.first]){
                auto record = st.find(make_pair(distance[neighbour.first], neighbour.first));
                //step d: If record found, then erase it.
                if(record != st.end()){
                    st.erase(record);
                }
                //step e: Distance update
                distance[neighbour.first] = nodeDistance + neighbour.second;
                //step f: Record push in set
                st.insert(make_pair(distance[neighbour.first], neighbour.first));
            }
        }
    }
    return distance;
}

