vector<pair<pair<int, int>, int>> calculatePrimsMST(int n, int m, vector<pair<pair<int, int>, int>> &g)
{
    //Create an Adjacency List
    unordered_map<int, list<pair<int, int> > > adj;
    for(int i=0; i<g.size(); i++)
    {
        int u = g[i].first.first;
        int v = g[i].first.second;
        int weight = g[i].second;
        adj[u].push_back(make_pair(v,weight));
        adj[v].push_back(make_pair(u,weight));
    }
    vector<int> key(n+1);    //Coz we r representing (index = node da number)
    vector<bool> mst(n+1);
    vector<int> parent(n+1);
    for(int i=0; i<=n; i++)
    {
        key[i] = INT_MAX;
        parent[i] = -1;
        mst[i] = false;
    }
    //Let's Start the algo
    //Step 1: Mark parent[source] = 1 and distance[source] = 0
    parent[1] = -1;
    key[1] = 0;
    //Step 2: Start comparing the source to next node
    for(int i=1; i<n; i++)
    {
        int mini = INT_MAX;
        int u;
        //Find min vali node
        for(int v=1; v<=n; v++){
            if(mst[v] == false && key[v] < mini){
                u = v;
                mini = key[v];
            }
        }
        //Mark min vali node as true
        mst[u] = true;
        //Check its adjacent Nodes
        for(auto i: adj[u]){
            int v = i.first;
            int weight = i.second;
            if(mst[v] == false && weight < key[v]){
                parent[v] = u;
                key[v] = weight;
            }
        }
    }
    //Here, our parent array will be prepared to return
    vector<pair<pair<int, int> , int>> result;
    for(int i=2; i<=n; i++)    //coz key[parent or 1] = 0
    {
        result.push_back({{parent[i], i}, key[i]});    //((initial, final), weight).
    }
    return result;
}

