#include <algorithm>
bool cmp(vector<int> &a , vector<int> &b){    //custom comparater to return values in ascending order
    return a[2] < b[2];
}
void makeSet(vector<int> &rank, vector<int> &parent, int node){
    for(int i=0; i<node; i++){
        parent[i] = i;
        rank[i] = 0;
    }
}
int findParent(vector<int> &parent, int node){
    //Base case
    if(parent[node] == node){
        return node;
    }
    parent[node] = findParent(parent, parent[node]);    //Path compression
}
void unionSet(int u, int v, vector<int> &parent, vector<int> &rank){
    u = findParent(parent, u);
    v = findParent(parent, v);
    //Node with greater rank will always be a Parent of Node.
    if(rank[u] < rank[v]){
        parent[u] = v;
    }
    else if(rank[v] < rank[u]){
        parent[v] = u;
    }
    else{    //If rank is same then increment rank and Make joints randomly
        parent[v] = u;
        rank[u]++;
    }
}
int minimumSpanningTree(vector<vector<int>>& edges, int n)
{
    sort(edges.begin(), edges.end(), cmp);    //cmp is custom comparater used to return value in ascending order
    vector<int> rank(n);
    vector<int> parent(n);
    makeSet(rank, parent, n);
    int minWeight = 0;
    for(int i=0; i<edges.size(); i++)
    {
        int u = findParent(parent, edges[i][0]);
        int v = findParent(parent, edges[i][1]);
        int wt = edges[i][2];
        if(u != v)    //Means parents of both are different and both
                      //belongs to different components
        {
            minWeight += wt;
            unionSet(u, v, parent, rank);        //Make union of both nodes
        }
    }
    return minWeight;
}

