/* Count number of Strongly connected components using Kosaraju's Algorithm



Strongly connected Components ---

A directed graph is said to be strongly connected if every vertex is reachable from every other vertex. The strongly connected components of a graph are the subgraphs which are themselves strongly connected.

*/





#include <unordered_map>

#include <list>

#include <stack>



//Topological sorting

void dfs(int node, unordered_map<int, bool> &visited, stack<int> &st,

                unordered_map<int, list<int> > &adj)

{

    visited[node] = true;

    for(auto neighbour : adj[node]){

        if(!visited[neighbour]){

            dfs(neighbour, visited, st, adj);

        }

    }

    //Topological sort Logic

    st.push(node);

}



void reverseDFS(int node, unordered_map<int, bool> &visited, 

               unordered_map<int, list<int> > &adj){

    visited[node] = true;

    for(auto neighbour : adj[node]){

        if(!visited[neighbour]){

            reverseDFS(neighbour, visited, adj);

        }

    }

}



int stronglyConnectedComponents(int v, vector<vector<int>> &edges)

{

	// Create an adjacency List

    unordered_map<int, list<int> > adj;

    for(int i=0; i<edges.size(); i++){

        int u = edges[i][0];

        int v = edges[i][1];



        adj[u].push_back(v);

    }



    //Step 1: Topological sort

    stack<int> st;

    unordered_map<int, bool> visited;

    for(int i=0; i<v; i++){

        if(!visited[i]){

            dfs(i, visited, st, adj);

        }

    }



    //Step 2: Create a Transpose Graph (reverse the direction of every edge).

    //coz stack follows LIFO rule, so to get result in right order this is done

    unordered_map<int, list<int> > transpose;

    for(int i=0; i<v; i++){

        visited[i] = 0;

        for(auto neighbour : adj[i]){

            transpose[neighbour].push_back(i);

        }

    }



    //Step 3: Call DFS for above ordering

    int count = 0;

    while(!st.empty()){

        int top = st.top();

        st.pop();

        if(!visited[top]){

            count++;

            reverseDFS(top, visited, transpose);

        }

    }

    return count; 

}

