class Solution {
public:
    int solve(vector<int> &cost, int n){
        //Base case
        if(n == 0){
            return cost[0];
        }
        if(n == 1){
            return cost[1];
        }
//Cost of Last stair is zero but before that cost will be considered
        int ans = cost[n] + min(solve(cost, n-1), solve(cost, n-2));
        return ans;
