int solveRec(vector<int> &weight, vector<int> &value, int index, int capacity){
    //Base case
    //If there is only 1 item to steal
    if(index == 0){
        if(weight[0] <= capacity)    //if weight is less than equal to capacity
            return value[0];
        else
            return 0;
    }
    int include = 0;
    if(weight[index] <= capacity){    //include that weight & recursive call for next index after subtracting
                                      //that weight from total one
        include = value[index] + solveRec(weight, value, index - 1, capacity - weight[index]);
    }
    //Else, Don't include value of that index and don't subtract it's weight from total
    int exclude = 0 + solveRec(weight, value, index - 1, capacity);
    int ans = max(include, exclude);
    return ans;
}
