int solveMemo(int n, vector<int>& days, vector<int>& cost, int index,
                                        vector<int> &dp)
{
    //Base case
    if(index >= n){    //Means we get out of the array or at last index.
                       // so, no need to buy pass
        return 0;
    }
    //Step 3:
    if(dp[index] != -1){
        return dp[index];
    }
    // 1 day pass
    int option1 = cost[0] + solveMemo(n, days, cost, index+1, dp);
    int i;
    // 7 days pass
    for(i = index; i<n && days[i] < days[index]+7; i++);
    int option2 = cost[1] + solveMemo(n, days, cost, i, dp);
    // 30 days pass
    for(i = index; i<n && days[i] < days[index] + 30; i++);
    int option3 = cost[2] + solveMemo(n, days, cost, i, dp);
    //Step 2:
    dp[index] = min(option1, min(option2, option3));
    return dp[index];
}

int solveTab(int n, vector<int>& days, vector<int>& cost)
{
    //Step 1:
    vector<int> dp(n+1, INT_MAX);
    //Step 2: Analyse Base case
    dp[n] = 0;	//dp of last
    //Step 3: Traversing from Right to left
    for(int k = n-1; k>=0; k--){
        // 1 day pass
        int option1 = cost[0] + dp[k+1];
        int i;
        // 7 days pass
        for(i = k; i<n && days[i] < days[k]+7; i++);
        int option2 = cost[1] + dp[i];
        // 30 days pass
        for(i = k; i<n && days[i] < days[k] + 30; i++);
        int option3 = cost[2] + dp[i];
        //Step 2:
        dp[k] = min(option1, min(option2, option3));
    }
    return dp[0];
}
int minimumCoins(int n, vector<int> days, vector<int> cost)
{
    return solveTab(n, days, cost);
}

