    //Function to find the maximum number of meetings that can
    //be performed in a meeting room.
    static bool cmp(pair<int, int> a, pair<int, int> b){
        return a.second < b.second;
    }
    int maxMeetings(int start[], int end[], int n)
    {
        // step 1: Push startTime and endTime into vector.
        vector<pair<int, int>> v;   // {startTime, endTime}
        for(int i=0; i<n; i++){
            pair<int, int> p = make_pair(start[i], end[i]);
            v.push_back(p);
        }
        // step 2: Push new vector on the basis of endTime.
        sort(v.begin(), v.end(), cmp);
        // step 3: We have to do atleast first meeting, so consider first elemnt
        // as startTime and endTime and increment count only if prevEndTime < currStartTime.
        int count = 1;
        int endTime = v[0].second;
        for(int i=1; i<v.size(); i++){
            if(endTime < v[i].first){
                count++;
                endTime = v[i].second;         // update endTime.
            }
        }
        return count;
    }
};

