    static bool cmp(pair<int, pair<int,int>> a, pair<int, pair<int, int>> b){
        // if endTime is same then sort in ascending order as per index
        if(a.second.second == b.second.second)
            return a.first < b.first;
        return a.second.second < b.second.second;
    }
    vector<int> maxMeetings(int N,vector<int> &S,vector<int> &F){
        // step 1: Push startTime and endTime into vector.
        vector<pair<int, pair<int,int>>> v;   // {index,{startTime, endTime}}
        for(int i=0; i<N; i++){
            v.push_back({i+1, {S[i], F[i]}});
        }
        // Step 2: Sort the vector as per endTime.
        sort(v.begin(), v.end(), cmp);
        // step 3: We have to do atleast first meeting, so consider first elemnt
        // as startTime and endTime and increment count only if prevEndTime <   currStartTime.
        vector<int> ans;
        int endTime = v[0].second.second;
        ans.push_back(v[0].first);                    // Push index of first meet
        for(int i=0; i<v.size(); i++){
            if(endTime < v[i].second.first){
                ans.push_back(v[i].first);            // Push its index only
                endTime = v[i].second.second;         // update endTime.
            }
        }
        sort(ans.begin(), ans.end());
        return ans;
    }
