class Solution
{
    public:
    //Function to return the minimum cost of connecting the ropes.
    long long minCost(long long arr[], long long n) {
        // Using Priority Queue with Min Heap
        priority_queue<long long, vector<long long>, greater<long long>> pq;
        // Step 1: Push all elements into Min heap
        for(int i=0; i<n; i++)
            pq.push(arr[i]);
        // Step 2: Every time take two smallest elements and merge them, at last we'll
        // get minimum cost.
        long long cost = 0;
        while(pq.size() > 1)
        {
            long long first = pq.top();
            pq.pop();
            long long second = pq.top();
            pq.pop();
            long long mergedLen = first + second;
            cost = cost +  mergedLen;
            // Step 3: Push new Len into Heap
            pq.push(mergedLen);
        }
        return cost;
    }
};

