Node *delAddLastNode(Node *head){



    //Base case

    if(head == NULL)

        return NULL;



    //Single Node Linked List

    if(head->next == NULL)

        return head;



    //Step 1: Traverse to last node of LL

    Node* prev = NULL;

    Node* curr = head;



    while(curr -> next != NULL){

        prev = curr;

        curr = curr-> next;

    }



    //Step 2: Mark Last-> next = NULL

    prev -> next = NULL;



    //Step 3: Add last Deleted Node to Head.

    curr -> next = head;

    head = curr;



    return head;



}

