class Solution {
public:
    //Using Recursive approach	T.C: -  exponential
    //Use copy pen to understand inside condition of for Loop
    int solveRec(vector<int> &num, int amount)
    {
        // Base case
        if(amount == 0){
            return 0;
        }
        if(amount < 0){
            return INT_MAX;
        }
        int minimum = INT_MAX;
        for(int i=0; i<num.size(); i++){
            int ans = solveRec(num, amount-num[i]); //coz current coin's amount is subtracted and call for nxt
            if(ans != INT_MAX){
                minimum = min(minimum, 1+ans);     //coz we considered num[i] wala coin but not its cost
            }
        }
        return minimum;
    }
     //Using Top down approach (Recursion + Memoization).
    //T.C: - O(x * n)	x is total amount , n is number of coins
    //S.C: - O(x)	x is total amount
    //Use copy pen to understand inside condition of for Loop
    int solveMemo(vector<int> &num, int amount, vector<int> &dp)
    {
        // Base case
        if(amount == 0){
            return 0;
        }
        if(amount < 0){
            return INT_MAX;
        }
        //Step 3: If answer is already present in dp then return it without going into recursive call
        if(dp[amount] != -1){
            return dp[amount];
        }
        int minimum = INT_MAX;
        for(int i=0; i<num.size(); i++){
            int ans = solveMemo(num, amount-num[i], dp); //coz current coin's amount is subtracted and call for nxt
            if(ans != INT_MAX){
                minimum = min(minimum, 1+ans);     //coz we considered num[i] wala coin but not its cost
            }
        }
        //Step 2: Store answer in dp
        dp[amount] = minimum;
        return dp[amount];
    }

    int solveTabu(vector<int> &num, int amount)
    {
        vector<int> dp(amount+1, INT_MAX);
        dp[0] = 0;
        for(int i=1; i <= amount; i++){
            //I'm trying to solve for every amount figure from 1 to x
            for(int j=0; j<num.size(); j++){
                if( i-num[j] >= 0 && dp[i-num[j]] != INT_MAX ){
                    dp[i] = min(dp[i], 1 + dp[i-num[j]] );
                }
            }
        }
        if(dp[amount] == INT_MAX){
            return -1;
        }
        return dp[amount];
    }
    int coinChange(vector<int>& coins, int amount) {
        return solveTabu(coins, amount);
    }
};

