    for(int w = weight[0]; w <= capacity; w++){
        if(weight[0] <= capacity)
            prev[w] = value[0];
        else
            prev[w] = 0;
    }
    //Step 3: Take care of Remaining Recursive calls
    // 2D dp
    for(int index = 1; index < n; index++){    //dp[Index] = curr & dp[Index-1] = prev
        for(int w = 0; w <= capacity; w++){
