int solveRec(vector<int> satisfaction, int index, int time)
{
    // Base case--- IF we reached out of index
    if(index == satisfaction.size())
        return 0;
    int ans = INT_MIN;
    // Include
    int include = satisfaction[index] * (time) + solveRec(satisfaction, index+1, time+1);
    // Exclude  (time will increase only if we include element otherwise, NO)
    int exclude =             0                  + solveRec(satisfaction, index+1, time);
    ans = max(include, exclude);
    return ans;
}

int f(vector<int> satisfaction, int index, int time, vector<vector<int> >& dp)
{
    // Base case
    if(index == satisfaction.size()){
        return 0;
    }
    // Step 2: Check if answer is already present in dp
    if(dp[index][time] != INT_MIN)   return dp[index][time];
    int include = satisfaction[index] * (time) + f(satisfaction, index+1, time+1, dp);
    int exclude =             0                  + f(satisfaction, index+1, time, dp);
    // Step 3: Store answer in dp and return
    return dp[index][time] = max(include, exclude);
}

int solveMem(vector<int>& satisfaction, int n, int i, int time, vector<vector<int>>& dp)
