int solveRec(vector<vector<char> > matrix, int row, int col, int & maximal)
{
    // Base case
    if(row >= matrix.size() || col >= matrix[0].size())
        return 0;
    /*
    To make square, we have to check four conditions
    -- if(curr == 1)
    -- if(right == 1)
    -- if(diagonal == 1)
    -- if(down == 1)
                        only then we can extend out square and increase area.
    */
    int right =     solveRec(matrix, row,   col+1, maximal);
    int diagonal =  solveRec(matrix, row+1, col+1, maximal);
    int down =      solveRec(matrix, row+1, col  , maximal);
    int size = 0;
    // Now check if(curr == 1)
    if(matrix[row][col] != '0')
    {
        /*
        Suppose we got right = 3, diagonal = 4, down = 1, then we can extend our square upto
        minimum value out of these three. So, add 1 + min( ,  ,  )  coz we have to add current's
        area too.
        */
        size = 1 + min(right, min(diagonal, down));
    }
    maximal = max(maximal, size);
    return size;
}

int solveMem(vector<vector<char> > matrix, int row, int col, int & maxSize,
                    vector<vector<int> > &dp)
{
    // Base case
    if(row >= matrix.size() || col >= matrix[0].size())
        return 0;
    // Step 2: Check if Answer is already present
    if(dp[row][col] != -1)  return dp[row][col];
    int right =     solveMem(matrix, row,   col+1, maxSize, dp);
    int diagonal =  solveMem(matrix, row+1, col+1, maxSize, dp);
    int down =      solveMem(matrix, row+1, col  , maxSize, dp);
    // Step 3:
    int size = 0;
    if(matrix[row][col] != '0')
    {
        size = 1 + min(diagonal, min(right, down));
    }
    maxSize = max(maxSize, size);
    return dp[row][col] = size;
}

    int memoization2(vector<vector<char> > matrix, vector<vector<int>> & dp)
    {
        int ans = 0;
        // Traversing Rows.
        for(int i=0; i<matrix.size(); i++)
        {
            // Traversing Columns
            for(int j=0; j<matrix[0].size(); j++)
            {
                // If we are at starting of row.
                if(i == 0 || j == 0)
                {
                    if(matrix[i][j] == '1')
                        dp[i][j] = 1;
                }
                else
                {
                    if(matrix[i][j] == '1')
                        dp[i][j] = 1 + min(dp[i-1][j], min(dp[i-1][j-1], dp[i][j-1]));
                }
                ans = max(ans, dp[i][j]);
            }
        }
        return ans*ans;     // coz we have to return its area at last.
    }
    int maximalSquare(vector<vector<char>>& matrix) {
        // int maximal = 0;
