    // Step 2: Analyse Base case
    // Traversing from Right to left of array
    for(int i=n; i>= 0; i--)
    {
        // if i == j        only one Node
        // if i == j+1      only two Nodes
        // if i == j=2      three nodes, (Perfect)
        for(int j=i+2; j<n; j++)
        {
            // Step 3: Convert Recursive Calls into dp and changes values of dp array by bottom up
            int ans = INT_MAX;
