class Solution {
public:
    int longestIncreasingSubsequence(vector<int> arr, int N, int curr, int prev){
        // Base case
        if(curr == N)
            return 0;
        // INCLUDE
        // We added one coz we want to add occurance of curr number too,
        // Now, curr is incremented and prev will point at curr.
        int pick = 0;
        if(prev == -1 || arr[curr] > arr[prev])
            pick = 1 + longestIncreasingSubsequence(arr, N, curr + 1, curr);
        // EXCLUDE
        // Now, prev will remain same coz we didn't include current number
        int notPick = 0 + longestIncreasingSubsequence(arr, N, curr + 1, prev);
        return max(pick, notPick);
    }

int solveMemo(vector<int>& arr, int curr, int prev, vector<vector<int> > & dp){
    // Base case
    if(curr == arr.size())      return 0;
    // Step 2: Check if answer is already present then return it
    // To handle edge case i.e. if(prev == -1), so always add 1 to prev
    if(dp[curr][prev+1] != -1)  return dp[curr][prev+1];
    // Step 3: Recursive calls and store answer in dp.
    // EXCLUDE
    // Now, prev will remain same coz we didn't include current number
    int notPick = 0 + solveMemo(arr, curr + 1, prev, dp);
    // INCLUDE
    // We added one coz we want to add occurance of curr number too,
    // Now, curr is incremented and prev will point at curr.
    int pick = 0;
    if(prev == -1 || arr[curr] > arr[prev])
        pick = 1 + solveMemo(arr, curr + 1, curr, dp);
    // We added prev+1 to get valid index coz for prev = -1 it will give error
    return dp[curr][prev+1] = max(pick, notPick);
}

