    {
        for(int prev = curr-1; prev >= -1; prev--)
        {
            // INCLUDE
            int pick = 0;
            if(prev == -1 || arr[curr] > arr[prev])
                pick = 1 + dp[curr + 1][curr + 1]; // prev + 2 means curr + 1 for second bracket
            // Exclude
            // We added prev+1 to get valid index coz for prev = -1 it will give error
            int notPick = 0 + dp[curr + 1][prev+1];
