    int solveRec(vector<int> & nums1, vector<int> & nums2, int index, bool swapped)
    {
        // Base case
        if(index == nums1.size())
            return 0;
        int ans = INT_MAX;
        int prev1 = nums1[index-1];
        int prev2 = nums2[index-1];
        /* CATCH
        If we swapped previous elements, but this was not done actually, so means we will
        check diagonally prev1 and prev2.
        Therefore, swap(prev1, prev2) coz we didn't make change these numbers in arrays.
        Read slides to understand this catch.        */
        if(swapped == true)
            swap(prev1, prev2);
        // No Swap          (If elements are already in increasing order).
        if(nums1[index] > prev1 && nums2[index] > prev2)
            ans = solveRec(nums1, nums2, index+1, false);
        // Swap             (consider current swap too, so we added 1)
                            // after swappinng, prev1 will become prev2 and vice versa.
        if(nums1[index] > prev2 && nums2[index] > prev1)
            ans = min(ans, 1 + solveRec(nums1, nums2, index+1, true));
        return ans;
    }

int solveMem(vector<int> & nums1, vector<int> & nums2, int index, bool swapped, vector<vector<int>> & dp)
{
    // Base case
    if(index == nums1.size())
        return 0;
    if(dp[index][swapped] != -1)       return dp[index][swapped];
    int ans = INT_MAX;
    int prev1 = nums1[index-1];
    int prev2 = nums2[index-1];
    if(swapped == true)     swap(prev1, prev2);
    // No Swap
    if(nums1[index] > prev1 && nums2[index] > prev2)
        ans = solveMem(nums1, nums2, index+1, false, dp);
    // Swap
    if(nums1[index] > prev2 && nums2[index] > prev1)
        ans = min(ans, 1 + solveMem(nums1, nums2, index+1, true, dp));
    dp[index][swapped] = ans;
    return dp[index][swapped];
}

int solveTab(vector<int> & nums1, vector<int> & nums2, int index, bool swapped)
{
    int n = nums1.size();
    vector<vector<int> > dp (n+1, vector<int> (2, 0));
    for(int index = n-1; index >= 1; index--)       // coz we know for n answer is 0 as per base case
    {
        for(int swapped = 1; swapped >= 0; swapped--)
        {
            // Copy previous code.
            int ans = INT_MAX;
            int prev1 = nums1[index-1];
