class Solution {
public:
    int longestSubsequence(vector<int>& arr, int difference) {
        int ans = 0;
        unordered_map<int,int> dp;
        // we r doing same as twoSum problem i.e. a + b = sum &
        // sum - a = b. So, we search for entry of 'b' in map
        // Just take a number and search backward a number with difference 'd'.
        // So we are doing the same with Tabulation
        for(int i = 0; i < arr.size(); i++)
        {
            int temp = arr[i] - difference;
            int tempAns = 0;
            if(dp.find(temp) != dp.end())
                tempAns = dp[temp];
            // current answer update
            dp[arr[i]] = 1 + tempAns;
            // update overall ans
            ans = max(ans, dp[arr[i]]);
        }
        return ans;
    }
};

