    ALGORITHM



STEP 1:

        IF 'i' is the root node, then there will be (i-1) nodes in left && (n-i) nodes in right

Also, we have two base cases that if only 1 or 0 node possible Tree is 1.



STEP 2:

        Traverse for every node in given range & consider it as a root and then add number of

trees for current node into ans





e.g.            (root 'i')

                /        \

    (1  to  i-1)          (i+1  to  n)





    i.e. (i-1) nodes in left

         (n-i) nodes in right.



         Total combinations for 'i' root = leftAns * rightAns



         Do same for every root and add different answers to 'ans'

*/



class Solution {

public:

    // RECURSION

    int solve(int n)

    {

        // Base case

        if(n <= 1)              // for '0' or '1' node possible tree is 1.

            return 1;



        int ans = 0;



        // consider everytime 'i' as root Node

        for(int i = 1; i <= n; i++) {

            ans += solve(i-1) * solve(n-i);    

        }

        return ans;

    }



    // MEMOIZATION

    int mem(int n, vector<int> &dp)

    {

        // Base case

        if(n <= 1)              

            return 1;



        if(dp[n] != -1)

            return dp[n];



        int ans = 0;

        for(int i = 1; i <= n; i++)

        {

            ans += mem(i-1, dp) * mem(n-i, dp);    

        }

        return dp[n] = ans;

    }



    // TABULATION

    int tab(int n)

    {

        vector<int> dp(n+1, 0);

        dp[0] = 1;

        dp[1] = 1;



        // We handled case of 0 and 1 now start from 2



        // i -> Number of Nodes

        for(int i = 2; i <= n; i++){



            // j -> Root nodes

            for(int j = 1; j <= i; j++){

                dp[i] += dp[j-1] * dp[i-j];         // Don't confuse just interchanging 'i' & 'j'

            }

        }

        return dp[n];

    }













    // SPACE OPTIMISATION

    // is just a Catalan Number



    int numTrees(int n)

    {

        long double ans = 1;

        for (int k = 2; k <= n; k++)

            ans *= (n + k), ans /= k;

        return ans;

    }



