class Solution {
public:
    int solve(int left, int right, vector<int> arr, map<pair<int,int>, int> & maxi)
    {
        // Base case -> If leaf node, then partition is not possible coz we can't get parent node
        // using only 1 node.
        if(left == right)
            return 0;
        int ans = INT_MAX;
        for(int i = left; i < right; i++)
        {
            int parent = maxi[{left, i}] * maxi[{i+1, right}]  +
                                     solve(left, i, arr, maxi) +
                                     solve(i+1, right, arr, maxi);
            ans = min(ans, parent);
        }
