// Dry Run to understand code.

class Solution {

public:

    int maxProfit(vector<int>& prices) {



        // Base case

        if(prices.size() == 1)

            return 0;



        int buy1 = INT_MAX;

        int profit1 = 0;



        int buy2 = INT_MAX;

        int profit2 = 0;



        for(int i=0; i<prices.size(); i++)

        {

            buy1 = min(buy1, prices[i]);

            profit1 = max(profit1, prices[i] - buy1);



            // Deduce the previous profit from newProfit.

            // effect / totalProfit will be found.



            buy2 = min(buy2, prices[i] - profit1);

            profit2 = max(profit2, prices[i] - buy2);

        }

        return profit2;

    }

};











// Follow Up Question of Buy and Sell Stock II

Only difference is, we can do atmost 2 transactions in it. So third parameter will be added in function i.e. Limit = 2

And a base case will be added.



Note: Limit will be decreased only if we do both buy and sell.

Rest is same as its second part question



/*

Case 1: Buy

    profit = profit - prices[i]



Case 2: Sell

    profit = profit + prices[i]

*/



class Solution {

public:

    // Recursion

    int solve(int i, int buyAllowed, vector<int> & prices, int limit){

        // Base case

        if(i == prices.size())  return 0;

        if(limit == 0)          return 0;



        int ans = 0;



        // Buy case

        if(buyAllowed){

            int buy     = -prices[i] + solve(i+1, 0, prices, limit);    

            int skipBuy =      0     + solve(i+1, 1, prices, limit);    



            ans = max(buy, skipBuy);

        }

        // Sale Case

        else{

            int sell     = prices[i] + solve(i+1, 1, prices, limit-1);   // limit will be dec only if we do both Buy & sell.

            int skipSell =     0     + solve(i+1, 0, prices, limit);    



            ans = max(sell, skipSell);

        }

        return ans;

    }



    // MEMOIZATION

    int mem(int i, int buyAllowed, vector<int> & prices, int limit, vector<vector<vector<int>>> & dp){

        // Base case

        if(i == prices.size())  return 0;

        if(limit == 0)          return 0;

        if(dp[i][buyAllowed][limit] != -1)

            return dp[i][buyAllowed][limit];



        int ans = 0;



        // Buy case

        if(buyAllowed){

            int buy     = -prices[i] + mem(i+1, 0, prices, limit, dp);    // Buy kro

            int skipBuy =      0     + mem(i+1, 1, prices, limit, dp);    // Ignore kro



            ans = max(buy, skipBuy);

        }

        // Sale Case

        else{

            int sell     = prices[i] + mem(i+1, 1, prices, limit-1, dp);     // Sale kro

            int skipSell =     0     + mem(i+1, 0, prices, limit, dp);     // Ignore kro



            ans = max(sell, skipSell);

        }

        return dp[i][buyAllowed][limit] = ans;

    }







    // TABULATION

    // Time Complexity: O(n*2*3)    / O(N)

    // Space Complexity: O(n*2*3)   / O(N)

    int tab(vector<int> &prices)

    {

        int n = prices.size();

        vector<vector<vector<int>>> dp(n+1, vector<vector<int>>(2, vector<int>(3, 0)));



        for(int i=n-1; i>=0; i--){

            for(int buyAllowed = 0; buyAllowed <= 1; buyAllowed++){

                for(int limit = 1; limit <= 2; limit++){



                    int ans = 0;



                    // Buy case

                    if(buyAllowed){

                        int buy     = -prices[i] + dp[i+1][0][limit];    // Buy kro

                        int skipBuy =      0     + dp[i+1][1][limit];    // Ignore kro



                        ans = max(buy, skipBuy);

                    }

                    // Sale Case

                    else{

                        int sell     = prices[i] + dp[i+1][1][limit-1];     // Sale kro

                        int skipSell =     0     + dp[i+1][0][limit];     // Ignore kro



                        ans = max(sell, skipSell);

                    }

                    dp[i][buyAllowed][limit] = ans;

                }

            }

        }

        return dp[0][1][2];

    }



    // SPACE OPTIMISATION

    // Time Complexity: O(N)

    // Space Complexity: O(1)



    int space(vector<int> &prices)

    {

        int n = prices.size();

        vector<vector<int>> curr(2, vector<int>(3, 0));

        vector<vector<int>> next(2, vector<int>(3, 0));



        for(int i=n-1; i>=0; i--){

            for(int buyAllowed = 0; buyAllowed <= 1; buyAllowed++){

                for(int limit = 1; limit <= 2; limit++){



                    int ans = 0;



                    // Buy case

                    if(buyAllowed){

                        int buy     = -prices[i] + next[0][limit];    // Buy kro

                        int skipBuy =      0     + next[1][limit];    // Ignore kro



                        ans = max(buy, skipBuy);

                    }

                    // Sale Case

                    else{

                        int sell     = prices[i] + next[1][limit-1];     // Sale kro

                        int skipSell =     0     + next[0][limit];     // Ignore kro



                        ans = max(sell, skipSell);

                    }

                    curr[buyAllowed][limit] = ans;

                }

            }

            next = curr;

        }

        return next[1][2];

    }



    int maxProfit(vector<int>& prices) {

        int index = 0;

        int buyAllowed = 1;

        int limit = 2;

        // return solve(index, buyAllowed, prices, limit);





        int n = prices.size();

        vector<vector<vector<int>>> dp(n, vector<vector<int>>(2, vector<int>(3, -1)));      // ('n' rows, '2' buy&sell, '3' limits)

                                                                                            // i.e. 0, 1, 2

        // return mem(index, buyAllowed, prices, limit, dp);







        // return tab(prices);







        return space(prices);

    }

};

