class Solution {
public:
    int lengthOfLIS(vector<int>& nums) {
        // coz len == 1 will be the minimum length of subsequence
        vector<int> dp(nums.size()+1, 1);
        int maxi = 1;
        // Step 1: Start Making your answer.
        for(int index = 0; index < nums.size(); index++) {
            // Compare with all previous and start making answer.
            for(int prev = 0; prev <= index-1; prev++) {
                if(nums[prev] < nums[index])
                    dp[index] = max(dp[index], 1 + dp[prev]);   // i.e. 1(curr) + longest subsequence
                                                                // till prev index.
            }
        }
        // Step 2: Get maximum subsequence out of all
        int result = 0;
        for(auto subCount : dp)
            result = max(result, subCount);
        return result;
    }
};

