        int ans = 0;

        if(a[i] == b[j])

            return mem(i+1, j+1, a, b, dp);

        else{

            // Insert

            int insertAns = 1 + mem(i, j+1, a, b, dp);                



            // Delete

            int deleteAns = 1 + mem(i+1, j, a, b, dp);                



            // Replace

            int replaceAns = 1 + mem(i+1, j+1, a, b, dp);            



            ans = min(insertAns, min(deleteAns, replaceAns));

        }

        return dp[i][j] = ans;

    }



    // TABULATION

    // Time : O(m*n)

    // Space: O(m*n)

    int tab(string a, string b)

    {

        vector<vector<int>> dp(a.size()+1, vector<int>(b.size()+1, 0));



        // Analyse Base case

        // 'i' -> row

        // 'j' -> col

        // When row is a.length ans will be this .....

        // When col is b.length ans will be this .....



        // Matlab   1.) Last  Saari  Row      (Horizontally)

        //          2.) Last  Saari  Column   (Vertically)



        // Means jdo row last ho jaave tan ohde de har ek column eh answer fill krdo

        for(int j=0; j < b.size(); j++)

            dp[a.length()][j] = b.size() - j;



        // Means har ek row de last index te eh answer fill krdo

        for(int i=0; i < a.size(); i++)

            dp[i][b.length()] = a.size() - i;







        for(int i = a.size()-1; i >= 0; i--){

            for(int j = b.size()-1; j >= 0; j--){



                int ans = 0;

                if(a[i] == b[j])

                    ans = dp[i+1][j+1];

                else{

                    // Insert

                    int insertAns = 1 + dp[i][j+1];                



                    // Delete

                    int deleteAns = 1 + dp[i+1][j];              



                    // Replace

                    int replaceAns = 1 + dp[i+1][j+1];          



                    ans = min(insertAns, min(deleteAns, replaceAns));

                }

                dp[i][j] = ans;

            }

        }

        return dp[0][0];

    }



    // SPACE OPTIMISATION

    int space(string a, string b)

    {

        vector<int> curr(b.size()+1, 0);

        vector<int> next(b.size()+1, 0);



        // Read Tabulation carefully to understand this

        // We can add these two loops while traversing too. i.e. Done at "LABEL"

        // We can remove these two loops

        for(int j=0; j < b.size(); j++)

            next[j] = b.size() - j;



        for(int i=0; i < a.size(); i++)

            curr[b.size()] = a.size() - i;







        for(int i = a.size()-1; i >= 0; i--){

            for(int j = b.size()-1; j >= 0; j--){



                // "LABEL"

                curr[b.size()] = a.size()-i;



                int ans = 0;

                if(a[i] == b[j])

                    ans = next[j+1];

                else{

                    // Insert

                    int insertAns = 1 + curr[j+1];                



                    // Delete

                    int deleteAns = 1 + next[j];              



                    // Replace

                    int replaceAns = 1 + next[j+1];          



                    ans = min(insertAns, min(deleteAns, replaceAns));

                }

                curr[j] = ans;

            }

            next = curr;

        }

        return next[0];

    }



    int minDistance(string word1, string word2) {



        // Base case



        // Coz we have to do insertion equals to number of characters in second

        if(word1.size() == 0)   return word2.size();

        if(word2.size() == 0)   return word1.size();





        // return solve(0, 0, word1, word2);





        vector<vector<int>> dp(word1.size(), vector<int>(word2.size(), -1));

        // return mem(0, 0, word1, word2, dp);





        // return tab(word1, word2);





        return space(word1, word2);

    }

};

