// T.C: O(N) + O(2E)	— E is number of edges or O(N) + O(total in & out degrees)

// S.C: O(N)	– N is number of nodes

class Solution {

  public:

    // Function to return Breadth First Traversal of given graph.

    vector<int> bfsOfGraph(int V, vector<int> adj[]) {

        vector<int> ans;

        vector<bool> visited (V, 0);

        queue<int> q;



        q.push(0);              // Push root of graph nd mark it visited

        visited[0] = true;



        while(!q.empty()){

            int curr = q.front();

            q.pop();

            ans.push_back(curr);



            for(auto elements : adj[curr])  // Extract List of elements at curr index and push into

                                            // queue if not visited.

            {

                if(!visited[elements]){

                    visited[elements] = true;

                    q.push(elements);

                }

            }

        }

        return ans;

    }

};

