        for(auto neighbour : adj[startNode])
        {
            if(!visited[neighbour])
                dfs(neighbour, adj, visited);
        }
    }
    int findCircleNum(vector<vector<int>>& isConnected) {
        // step 1: Convert Adjacency Matrix into adjacency List
        int v = isConnected.size();     // Number of Nodes.
        vector<int> adj[v];
        for(int i=0; i<v; i++){
            for(int j=0; j<v; j++){
                // If there is some node between i & j    &&    don't consider self Node.
                if(isConnected[i][j] == 1 && i != j){
                    adj[i].push_back(j);
                    adj[j].push_back(i);
                }
            }
        }
        // Step 2: Call DFS for every startingNode and count StartingNodes
        // Provinces  ==  StartingNodes
        vector<int> visited(v, 0);
        int start = 0 ;
        int count = 0;
        for(int i=0; i<v; i++){
            // when we encounter new StartingNode, increment provinces.
            if(!visited[i]){
                count++;
                dfs(i, adj, visited);
            }
        }
        return count;
    }
};

