class Solution {
public:
    void bfs(int row, int col, vector<vector<int>> & visited, vector<vector<char>> grid)
    {
        int n = grid.size();
        int m = grid[0].size();
        visited[row][col] = 1;
        queue<pair<int, int>> q;
        q.push({row, col});
        while(!q.empty()){
            int row = q.front().first;
            int col = q.front().second;
            q.pop();
            // Traverse in the neighbour and mark them if its an island
            // Neighbour can be in 8 directions. Suppose u r in middle of matrix & then think
            // about ur neighbours
            for(int delrow = -1; delrow <= 1; delrow++) {
                for(int delcol = -1; delcol <= 1; delcol++)
                {
                    if(delrow == -1&&delcol == 0||
                        delrow == 0&&delcol == 1||
                        delrow == 1&&delcol == 0||
                        delrow == 0&&delcol == -1)
                    {
                        int nrow = row + delrow;
                        int ncol = col + delcol;
                        if(nrow >= 0 && nrow < n &&         // Index must be in range
                           ncol >= 0 && ncol < m &&
                           grid[nrow][ncol] == '1' &&       // It must be land
                           !visited[nrow][ncol]) {          // It must be not visited
                            visited[nrow][ncol] = 1;
                            q.push({nrow, ncol});
                        }
                    }
                }
            }
        }
    }
    int numIslands(vector<vector<char>>& grid) {
        int n = grid.size();        // rows
        int m = grid[0].size();     // col
        // Step 1: Make visited matix as replica of given grid
        vector<vector<int>> visited (n, vector<int> (m, 0));
        // Step 2: Call BFS/DFS for startingNode or notVisited Node and mark them
        // and count startingNodes.
        int count = 0;
        for(int row = 0; row < n; row++){
            for(int col = 0; col < m; col++){
                // call bfs only if we encounter notVisited and its land
                if(!visited[row][col] && grid[row][col] == '1'){
                    count++;
                    bfs(row, col, visited, grid);
                }
            }
        }
        return count;
    }
};

