class Solution {
public:
    void dfs(int row, int col, vector<vector<int>> & ans, vector<vector<int>>& image,
                int initialColor, int newColor){
        // Base case
        // row and col must be in range
        if(row < 0 || row >= image.size() || col < 0 || col >= image[0].size() ||
           image[row][col] != initialColor ||       // if it's not desired color
            ans[row][col] == newColor){             // if it's is already modified with newColor
            return ;
        }
        ans[row][col] = newColor;
        dfs(row, col-1, ans, image, initialColor, newColor);    // Left
        dfs(row-1, col, ans, image, initialColor, newColor);    // Up
        dfs(row, col+1, ans, image, initialColor, newColor);    // Right
        dfs(row+1, col, ans, image, initialColor, newColor);    // Down
    }
    vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int color) {
        int initialColor = image[sr][sc];
        // Step 1: Make copy of image matrix and change colors in that but not in original one
        vector<vector<int>> ans = image;
        dfs(sr, sc, ans, image, initialColor, color);
        return ans;
    }
};

class Solution {
public:
    vector<vector<int>> floodFill(vector<vector<int>>& image, int sr, int sc, int color) {
        int n = image.size();
        int m = image[0].size();
        int initialColor = image[sr][sc];
        vector<vector<int>> visited(n, vector<int> (m, 0));
        queue<pair<int, int>> q;
        q.push({sr, sc});
        while(!q.empty()){
            int row = q.front().first;
            int col = q.front().second;
            q.pop();
            // Left
            if(col-1 >= 0 && image[row][col-1] == initialColor && visited[row][col-1] == 0){
                visited[row][col-1] = 1;
                q.push({row, col-1});
            }
            // Up
            if(row-1 >= 0 && image[row-1][col] == initialColor && visited[row-1][col] == 0){
                visited[row-1][col] = 1;
                q.push({row-1, col});
            }
            //Right
            if(col+1 < m && image[row][col+1] == initialColor && visited[row][col+1] == 0){
                visited[row][col+1] = 1;
                q.push({row, col+1});
            }
	// Down
            if(row+1 < n && image[row+1][col] == initialColor && visited[row+1][col] == 0){
                visited[row+1][col] = 1;
                q.push({row+1, col});
            }
            image[row][col] = color;
        }
        return image;
    }
};

