class Solution {
  public:
    // Function to detect cycle in an undirected graph.
    bool bfs(int src, vector<int> adj[], int vis[]){
        vis[src] = 1;
        // Store <Source Node, parent Node>
        queue<pair<int,int>> q;
        q.push({src, -1});      // Initially, Parent is -1;
        while(!q.empty()){
            int node = q.front().first;
            int parent = q.front().second;
            q.pop();
            // Go to all adjacent Nodes
            for(auto ele : adj[node])
            {
                if(!vis[ele]){
                    vis[ele] = 1;
                    q.push({ele, node});
                }
                //Otherwise, if node is already visited but current is not the parent of that node
                // if means, some other node at same level had visited it earlier
                // Hence, cycle detected
                else if(parent != ele){   // Create Adj List and then try to understand this condition
                    return true;
                }
            }
        }
        return false;
    }
    bool isCycle(int V, vector<int> adj[]) {
        int vis[V] = {0};
        for(int i=0; i<V; i++){
            if(!vis[i])
            {
                if( bfs(i, adj, vis))     return true;
            }
        }
        return false;
    }
};

