// Algorithm for this question





The algorithm steps are as follows:

Create a corresponding visited matrix and initialize it to 0.

Start with boundary elements, once ‘O’ is found, call the DFS function for that element and mark it as visited. In order to traverse for boundary elements, you can traverse through the first row, last row, first column, and last column. 

DFS function call will run through all the unvisited neighboring ‘O’s in all 4 directions and mark them as visited so that they are not converted to ‘X’ in the future. The DFS function will not be called for the already visited elements to save time, as they have already been traversed. 

When all the boundaries are traversed and corresponding sets of ‘O’s are marked as visited, they cannot be replaced with ‘X’. All the other remaining unvisited ‘O’s are replaced with ‘X’. This can be done in the same input matrix as the problem talks about replacing the values, otherwise tampering with data is not advised.











// Using DFS Algorithm

// It can be Done using BFS Algo too.



/*

step 1: Traverse all four boundaries of matrix i.e. first and last row & first and last col, and

        find 0's then call dfs for these 0's and corresponding 0's connected to these 0's

        While traversing mark them as visited, means these are not surrounded by X's and can't be converted



step 2: Traverse whole matrix and if we find '0' and it is not visited yet, then convert it into X.

*/



class Solution {

public:

    void dfs(int row, int col, vector<vector<bool>> & vis, vector<vector<char>>& matrix){

        vis[row][col] = 1;

        int n = matrix.size();

        int m = matrix[0].size();



        int delrow[] = {-1, 0, +1, 0};

        int delcol[] = {0, 1, 0, -1};



        // Traverse Neighbours i.e. left, right, top, bottom

        for(int i=0; i<4; i++){

            int nrow = row + delrow[i];

            int ncol = col + delcol[i];



            // check for valid coordinates and unvisited Os

            if(nrow >= 0 && nrow < n && ncol >= 0 && ncol < m &&

                !vis[nrow][ncol] && matrix[nrow][ncol] == 'O'){



                dfs(nrow, ncol, vis, matrix);

            }

        }

    }



    void solve(vector<vector<char>>& matrix) {

        int n = matrix.size();

        int m = matrix[0].size();



        vector<vector<bool>> vis (n, vector<bool> (m, 0));



        // Step 1: Traversing Boundaries and marking 0's as visited which are

        // connected to boundaries by DFS algo



        for(int j=0; j<m; j++){



            // First Row            (Means row will remain same but col will vary)

            if(!vis[0][j] && matrix[0][j] == 'O')

                dfs(0, j, vis, matrix);



            // Last Row             (Means row will remain same but col will vary)

            if(!vis[n-1][j] && matrix[n-1][j] == 'O')

                dfs(n-1, j, vis, matrix);

        }





        for(int i=0; i<n; i++){



            // First Col            (Mens col will remain same but row will vary)

            if(!vis[i][0] && matrix[i][0] == 'O')

                dfs(i, 0, vis, matrix);



            // Last Col             (Means col will remain same but col will vary)

            if(!vis[i][m-1] && matrix[i][m-1] == 'O')

                dfs(i, m-1, vis, matrix);

        }



        // Step 2: Traverse entire Matrix and convert all unvisited 0's into X's

        for(int i=0; i < n; i++){

            for(int j=0; j < m; j++){

                if(!vis[i][j] && matrix[i][j] == 'O'){

                    matrix[i][j] = 'X';

                }

            }

        }

    }

};

