class Solution {
public:
    void dfs(int row, int col, vector<vector<int>> & grid){
        int n = grid.size();
        int m = grid[0].size();
        if(row<0 || row>=n || col<0 || col>=m || grid[row][col] != 1)
            return;
        grid[row][col] = 0;
        // Traverse in all four directions
        dfs(row+1, col, grid);
        dfs(row, col+1, grid);
        dfs(row-1, col, grid);
        dfs(row, col-1, grid);
    }
    int numEnclaves(vector<vector<int>>& grid) {
        int n = grid.size();
        int m = grid[0].size();
        // Step 1: Traverse Boundaries and call dfs for corresponding 1's and modify them as 0
        // instead of using visited array, we are marking them as 0's
        // But we have to Return the number of land cells in grid for which we cannot walk off the         // boundary of the grid in any number of moves.
        for(int j=0; j<m; j++){
            //first Row
            if(grid[0][j] == 1)
                dfs(0, j, grid);
            // Last row
            if(grid[n-1][j] == 1)
                dfs(n-1, j, grid);
        }
        for(int i=0; i<n; i++){
            //First col
            if(grid[i][0] == 1)
                dfs(i, 0, grid);
            // Last col
            if(grid[i][m-1] == 1)
                dfs(i, m-1, grid);
        }
        // Step 2: Traverse the entire grid and count all remaning 1's
        int isLand = 0;
        for(int i=0; i<n; i++){
            for(int j=0; j<m; j++){
                if(grid[i][j] == 1)
                    isLand++;
            }
        }
        return isLand;
    }
};

class Solution {
public:
    int numEnclaves(vector<vector<int>>& grid) {
        queue<pair<int,int>> q;
        int n = grid.size();
        int m = grid[0].size();
        vector<vector<int>> vis (n, vector<int> (m, 0));
        // traverse boundary elements
        for(int i = 0;i<n;i++) {
            for(int j = 0;j<m;j++) {
                // first row, first col, last row, last col
                if(i == 0 || j == 0 || i == n-1 || j == m-1) {
                    // if it is a land then store it in queue
                    if(grid[i][j] == 1) {
                        q.push({i, j});
                        vis[i][j] = 1;
                    }
                }
            }
        }
        int delrow[] = {-1, 0, +1, 0};
        int delcol[] = {0, +1, +0, -1};
        while(!q.empty()) {
            int row = q.front().first;
            int col = q.front().second;
            q.pop();
            // traverses all 4 directions
            for(int i = 0;i<4;i++) {
                int nrow = row + delrow[i];
                int ncol = col + delcol[i];
                // check for valid coordinates and for land cell
                if(nrow >=0 && nrow <n && ncol >=0 && ncol < m
                && vis[nrow][ncol] == 0 && grid[nrow][ncol] == 1) {
                    q.push({nrow, ncol});
                    vis[nrow][ncol] = 1;
                }
            }
        }
        int cnt = 0;
        for(int i = 0;i<n;i++) {
            for(int j = 0;j<m;j++) {
                // check for unvisited land cell
                if(grid[i][j] == 1 & vis[i][j] == 0)
                    cnt++;
            }
        }
        return cnt;
    }
};

