        int n = grid.size();
        int m = grid[0].size();
        vector<vector<int>> vis (n, vector<int> (m, 0));
        set<vector<pair<int, int>>> s;
        // Step 1: Traverse every row & col and store shapes/coordinates in vector by using formula
