class Solution {
public:
    bool bfs(int start, int V, vector<int> adj[], vector<int> & color)
    {
        queue<int> q;
        q.push(start);
        color[start] = 0;          // Let's start with color 0 for first/startingNode
        while(!q.empty())
        {
            int currNode = q.front();
            q.pop();
            for(auto node: adj[currNode])
            {
                if(color[node] == color[currNode])          // If two adjacent Nodes have same colour
                    return false;
                else if(color[node] == -1)                  // If not colored, call bfs for it & color it
                {
                    color[node] = !color[currNode];
                    q.push(node);
                }
            }
        }
        return true;
    }
	bool isBipartite(int V, vector<int>adj[]){
	    vector<int> color (V, -1);
	    // Assuming that there would be stronly connected components
	    for(int i=0; i<V; i++)
	    {
	        // If not coloured, then call bfs and colour adjacent Nodes with opposite color
	        if(color[i] == -1)
	        {
	            // if we get two adjacent nodes having same color, then it can't be Bipartite Graph
	            if(bfs(i, V, adj, color) == false)
	                return false;
	        }
	    }
	    // if we are able to color all nodes of graph that means, its a Bipartite
