class Solution {
public:
    unordered_map<int, vector<int>> adj;
    bool dfs(int node, vector<int> &color)
    {
        for(auto it: adj[node])
        {
            // If not colored, Mark opposite color and call dfs
            if(color[it] == -1){
                color[it] = !color[node];
                if(!dfs(it, color))
                    return false;
            }
            // If already colored, check condition
            else if(color[it] == color[node])
                return false;
        }
        return true;
    }
    bool possibleBipartition(int n, vector<vector<int>>& dislikes) {
        // Step 1: Make Adjacency List starting from 1 to n
        for(int i=0; i<dislikes.size(); i++){
            vector<int> temp = dislikes[i];
            int u = temp[0];
            int v = temp[1];
            adj[u].push_back(v);    // As person U and V don't like each other.
            adj[v].push_back(u);    // So, consider both are parents of each other.
        }
        // Step 2: Using DFS, Pick every person and put its all neighbours into second team
        // As they don't like each other
        vector<int> color(n+1, -1);
        for(int node=1; node<=n; node++)
        {
            // If Not coloured, take every neighbour and make it with opposite color using BFS
            if(color[node] == -1)
            {
                color[node] = 1;
                if(!dfs(node, color))
                    return false;
            }
        }
        return true;
    }
};

