	        e.g.
	        0 ->
	        1 ->
	        2 -> { 3 }      Indegree of 3 becomes 1
	        3 -> { 1 }      Indegree of 1 becomes 1
	        4 -> { 0, 1 }   Indegree of 0 becomes 1 & 1 becomes 2
	        5 -> { 0, 2 }   Indegree of 0 becomes 2 & 2 becomes 1
	    */
	    // Step 1:
	    for(int i=0; i < V; i++){
	        for(auto it: adj[i])
	            inDegree[it]++;
	    }
	    // Step 2:
	    queue<int> q;
	    for(int i=0; i < V; i++){
	        if(inDegree[i] == 0)
	            q.push(i);
	    }
	    // Step 3:
	    vector<int> topo;
	    while(!q.empty())
	    {
	        int node = q.front();
	        q.pop();
	        topo.push_back(node);
	        // node is in your topo sort
	        // so please remove it from the indegree too.
	        for(auto it: adj[node]){
	            inDegree[it]--;
	            if(inDegree[it] == 0)
	                q.push(it);
	        }
	    }
	    return topo;
	}
};

