class Solution {
public:
    // Using BFS or Kahn's Algo or Topological Sort
    bool bfs(int n, vector<vector<int>> prerequisites) {
        // Convert edges into graph
        vector<int> graph[n];
        for(auto it: prerequisites){
            int u = it[0];
            int v = it[1];
            graph[v].push_back(u);
        }
        // Step 1: Find Indegree of all elements.
        vector<int> inDegree(n, 0);
        for(int i=0; i < n; i++) {
            for(auto it: graph[i]){
                inDegree[it]++;
            }
        }
        // Step 2: Start BFS and push all elements having indegree '0' into Queue
        queue<int> q;
        for(int i=0; i < n; i++) {
            if(inDegree[i] == 0)
                q.push(i);
        }
        vector<int> topo;
        while(!q.empty())
        {
            int node = q.front();
            q.pop();
            topo.push_back(node);
            for(auto child: graph[node]) {
                inDegree[child]--;
                if(inDegree[child] == 0)
                    q.push(child);
            }
        }
        // No cycle found, Courses can be schedule
        if(topo.size() == n)
            return true;
        return false;
    }
    // USING STANDARD DFS ALGORITHM for Topological Sort
    bool isCycle(int src, vector<int> &vis, vector<int> &pathvisit, vector<int> graph[]) {
        vis[src] = 1;
        pathvisit[src] = 1;
        for(auto child: graph[src])
        {
            if(!vis[child]) {
                if(isCycle(child, vis, pathvisit, graph) == true)
                    return true;
            }
            else if(vis[child] && pathvisit[child])
                return true;
        }
        pathvisit[src] = 0;
        return false;
