class Solution {
public:
    // Using BFS or Kahn's Algo or Topological Sort
    vector<int> bfs(int n, vector<vector<int>> prerequisites) {
        // Convert edges into graph
        vector<int> graph[n];
        for(auto it: prerequisites){
            int u = it[0];
            int v = it[1];
            graph[v].push_back(u);
        }
        // Step 1: Find Indegree of all elements.
        vector<int> inDegree(n, 0);
        for(int i=0; i < n; i++) {
            for(auto it: graph[i]){
                inDegree[it]++;
            }
        }
        // Step 2: Start BFS and push all elements having indegree '0' into Queue
        queue<int> q;
        for(int i=0; i < n; i++) {
            if(inDegree[i] == 0)
                q.push(i);
        }
        vector<int> topo;
        while(!q.empty())
        {
            int node = q.front();
            q.pop();
            topo.push_back(node);
            for(auto child: graph[node]) {
                inDegree[child]--;
                if(inDegree[child] == 0)
                    q.push(child);
            }
        }
        if(topo.size() == n)
            return topo;
        return {};
    }
    // USING STANDARD DFS ALGORITHM for Cyclic check in Directed Graph.
    bool isCycle(int node, stack<int> &st, vector<int> adj[], vector<int> & vis, vector<int> &pathVis){
        vis[node] = 1;
        pathVis[node] = 1;
        // Traverse Adjacent Nodes
        for(auto neighbour: adj[node]){
            if(!vis[neighbour]){
                if(isCycle(neighbour, st, adj, vis, pathVis) == true)
                    return true;
            }
            // Cycle Detected
            else if(vis[neighbour] && pathVis[neighbour])
                return true;
        }
        pathVis[node] = 0;      // While returning from recursive call, mark pathVis as false
        st.push(node);
        return false;
    }
    vector<int> findOrder(int n, vector<vector<int>>& p) {
        // return bfs(n, p);
        // Convert edges into graph
        vector<int> graph[n];
        for(auto it: p){
            int u = it[0];
            int v = it[1];
            graph[v].push_back(u);
        }
        vector<int> vis(n, 0);
        vector<int> pathvis(n, 0);
        stack<int> st;
        for(int i=0; i < n; i++) {
            if(!vis[i]) {
                if(isCycle(i, st, graph, vis, pathvis) == true)
                    return {};
            }
        }
        vector<int> ans;
        while(!st.empty())
        {
            ans.push_back(st.top());
            st.pop();
        }
        return ans;
    }
};

