                return true;

        }





        pathVis[node] = 0;      // While returning from recursive call, mark pathVis as false

        st.push(node);

        return false;  

    }





    vector<int> findOrder(int n, vector<vector<int>>& p) {



        // return bfs(n, p);











        // Convert edges into graph

        vector<int> graph[n];



        for(auto it: p){

            int u = it[0];

            int v = it[1];



            graph[v].push_back(u);

        }



        vector<int> vis(n, 0);

        vector<int> pathvis(n, 0);

        stack<int> st;



        for(int i=0; i < n; i++) {

            if(!vis[i]) {

                if(isCycle(i, st, graph, vis, pathvis) == true)

                    return {};

            }

        }



        vector<int> ans;



        while(!st.empty())

        {

            ans.push_back(st.top());

            st.pop();

        }

        return ans;

    }

};

