class Solution {
public:
    vector<int> bfs(int V, vector<vector<int>> adj) {
        vector<vector<int>> graph(V);               // Adjacency Matrix
        vector<int> inDegree(V, 0);
        // Step 1: Reverse all the edges and calculate inDegree of all neighbour nodes simultaneously
        for(int i=0; i < V; i++){
            // i -> it
            // it-> i
            for(auto it: adj[i]){
                graph[it].push_back(i);        // Reverse Edge
                inDegree[i]++;                  // calculate inDegree of Neighbour
            }
        }
        // Step 2: Push all the nodes having InDegree == 0 into queue
        queue<int> q;
        for(int i=0; i < V; i++){
            if(inDegree[i] == 0)
                q.push(i);
        }
        // Step 3: Start Topological sort using BFS or Kahn's Algo
        // Now, the node having inDegree is considered to be SafeNode
        // And, we will push Node into queue only if inDegree == 0
        vector<int> safeNodes;
        while(!q.empty()) {
            int node = q.front();
            q.pop();
            safeNodes.push_back(node);
            for(auto nbr: graph[node]) {
                inDegree[nbr]--;            // We we go to nbr using path 1, InDegree decreases
                                            // and that nodes is considered as startingPoint itself
                if(inDegree[nbr] == 0)
                    q.push(nbr);
            }
        }
        sort(safeNodes.begin(), safeNodes.end());
        return safeNodes;
    }
    vector<int> eventualSafeNodes(vector<vector<int>>& graph) {
        int V = graph.size();
        return bfs(V, graph);
    }
};

