class Solution{
    public:
    vector<int> topo(unordered_map<int, list<int>> & adj, int V) {
        // i.) Get Indegree of all Nodes.
        int inDegree[V] = {0};
        for(int i = 0; i < V; i++) {
            for(auto it : adj[i]) {
                inDegree[it]++;
            }
        }
        // ii.) Push the nodes having inDegree == 0 into queue
        queue<int> q;
        for(int i = 0; i < V; i++) {
            if(inDegree[i] == 0)
                q.push(i);
        }
        // iii.) Start TopoSort
        vector<int> topo;
        while(!q.empty()) {
            int node = q.front();
            q.pop();
            topo.push_back(node);
            for(auto nbr: adj[node]) {
                inDegree[nbr]--;
                if(inDegree[nbr] == 0)
                    q.push(nbr);
            }
        }
        return topo;
    }
    string findOrder(string dict[], int N, int K) {
        // Step 1:
        // Take two strings every time and traverse them until we are
        // getting same value.
        // Once we get unequal character cosider upper one as 'u' and
        // lower as 'v' & make adjacency list.
        unordered_map<int, list<int>> adj;
        for(int ptr = 0; ptr < N-1; ptr++) {
            string s1 = dict[ptr];
            string s2 = dict[ptr+1];
            int len = min(s1.size(), s2.size());
            for(int i = 0; i < len; i++) {
                if(s1[i] != s2[i]) {
                    int u = s1[i] - 'a';
                    int v = s2[i] - 'a';
                    adj[u].push_back(v);
                    break;
                }
            }
        }
        // Step 2: After making adjacency list, apply
        // topoSort and get ordering of character int string.
        vector<int> ans = topo(adj, K);
        // Converting into string.
        string str = "";
        for(int i = 0; i < ans.size(); i++) {
            str.push_back(ans[i] + 'a');
        }
        return str;
    }
};

