     vector<int> shortestPath(int N,int M, vector<vector<int>>& edges){
        // Step 1: Edges to weighted directed graph
        vector<pair<int,int>> adj[N];               // u -> {v, wt}
        for(int i=0; i < edges.size(); i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            int wt = edges[i][2];
            adj[u].push_back({v, wt});
        }
        // Step 2: Topo sort to get Linear ordered in vector / stack
        stack<int> st;
        int vis[N] = {0};
        for(int i = 0; i < N; i++) {
            if(!vis[i])
                topoSort(i, st, vis, adj);
        }
        vector<int> arr;
        while(!st.empty()) {
            int node = st.top();
            st.pop();
            arr.push_back(node);
        }
        // Step 3: Do Distance thing.
        vector<int> dist(N, 1e9);
        int src = 0;
        dist[src] = 0;                      // coz src to src's distance is '0'
        for(int u = 0; u < arr.size(); u++) {
            for(auto it : adj[u]) {
                int v = it.first;
                int wt = it.second;
                // If destination's dist is less than curr path's distance.
                // update it.
                if(dist[u] + wt < dist[v])
                    dist[v] = dist[u] + wt;
            }
        }
        for(int i=0; i < dist.size(); i++) {
            if(dist[i] == 1e9)
                dist[i] = -1;
        }
        return dist;
    }
};

