class Solution {
public:
    int ladderLength(string startWord, string targetWord, vector<string>& wordList) {
        // Instead of using visited array we are using 'set' data structure.
        unordered_set<string> st(wordList.begin(), wordList.end());
        queue<pair<string,int>> q;
        q.push({startWord, 1});
        st.erase(startWord);            // just like mark as visited.
        while(!q.empty()) {
            string word = q.front().first;
            int steps = q.front().second;
            q.pop();
            // If we get out targetWord after transformations.
            if(word == targetWord)
                return steps;
            // Try to change every character of word from 'a' to 'z'
            // and if modified word exists in set push it into queue with step+1.
            // Otheriwse, just change the char into original one after the entire loop
            for(int i=0; i < word.size(); i++) {
                char original = word[i];
                for(char ch = 'a'; ch <= 'z'; ch++) {
                    word[i] = ch;
                    // If word exists, push it into set and mark as visited by removing it.
                    if(st.count(word)) {
                        st.erase(word);		// Remove from set just like mark as visited
                        q.push({word, steps+1});
                    }
                }
                word[i] = original;
            }
        }
        // If we don't get our targetWord afte all transformations, return 0
        return 0;
    }
};

