class Solution {
  public:
    vector<int> shortestPath(int n, int m, vector<vector<int>>& edges) {
        // REMEMBER EVERY ARRAY OF GRAPH SHOULD BE 1-BASED AS PER THE QUESTION
        // Step 1: Edges to graph
        vector<pair<int,int>> adj[n+1];
        for(auto it: edges) {
            int u = it[0];
            int v = it[1];
            int wt = it[2];
            adj[u].push_back({v, wt});
            adj[v].push_back({u, wt});
        }
        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> q;
        vector<int> dist(n+1, 1e9);
        vector<int> parent(n+1);
        // Initially, parent of every node is itself.
        for(int i=0; i < parent.size(); i++)
            parent[i] = i;
        // Step 2: Start BFS            (Dry Run to understand the parent wala concept
        //                                     or watch video lecture of striver)
        dist[1] = 0;
        q.push({1, 0});
        while(!q.empty()) {
            auto it = q.top();
            int node = it.first;
            int dis = it.second;
            q.pop();
            for(auto it: adj[node]) {
                int adjNode = it.first;
                int edgeWt = it.second;;
                if(dis + edgeWt < dist[adjNode]) {
                    dist[adjNode] = dis + edgeWt;
                    q.push({adjNode, dist[adjNode]});
                    parent[adjNode] = node;                 // Mark the node from where it is coming
                }
            }
        }
        // If destination is not reachable
        if(dist[n] == 1e9) {
            return {-1};
        }
        // Extract path by traversing from destination & choosing its parent everytime
        else {
            vector<int> path;
            int node = n;                                   // Traverse from destination (Top Down)
            while(parent[node] != node) {                   // it will terminate at 1 when parent[1] = 1.
                path.push_back(node);
                node = parent[node];
            }
            path.push_back(1);              // push last node.
            reverse(path.begin(), path.end());
            return path;
        }
    }
};

