class Solution {
  public:
    int shortestPath(vector<vector<int>> &grid, pair<int, int> source,
                     pair<int, int> destination) {
        int rows = grid.size();
        int cols = grid[0].size();
        vector<vector<int>> dist (rows, vector<int> (cols, 1e9));
        queue<pair<int, pair<int,int>>> q;
        int srcRow = source.first;
        int srcCol = source.second;
        int dr[] = {-1, 0, 1, 0};                       // For Traversing in all four directions.
        int dc[] = {0, 1, 0, -1};
        // Start Dijkstra's Algo.
        dist[srcRow][srcCol] = 0;
        q.push({0, {srcRow, srcCol}});
        while(!q.empty()) {
            auto it = q.front();
            q.pop();
            int dis = it.first;
            int r = it.second.first;
            int c = it.second.second;
            // Traverse all Four directions.
            for(int i=0; i < 4; i++) {
                int newR = r + dr[i];
                int newC = c + dc[i];
                // Check for validity, element == 1 && currDis < prevDis
                if(newR >= 0 && newR < rows && newC >= 0 && newC < cols &&
                    grid[newR][newC] == 1 && dis + 1 < dist[newR][newC])
                    {
                        dist[newR][newC] = dis + 1;
                        // IF we get our destination.
                        if(newR == destination.first && newC == destination.second)
                            return dis + 1;
                        q.push({dis + 1 ,{newR, newC}});
                    }
            }
        }
        // If We are already at our Destination
        if(source.first == destination.first && source.second == destination.second)
            return 0;
        // Return -1 if we don't get our destination.
        return -1;
    }
};

