class Solution {
  public:
    bool isValid(int nr, int nc, int n, int m) {
        return nr >= 0 && nr < n && nc >= 0 && nc < m;
    }
    int MinimumEffort(vector<vector<int>>& arr) {
        // {Diff , {row, col}}
        priority_queue<pair<int,pair<int,int>>,
            vector<pair<int,pair<int,int>>>, greater<pair<int,pair<int,int>>>> pq;
        int n = arr.size(), m = arr[0].size();
        vector<vector<int>> dist(n, vector<int> (m, 1e9));
        int dr[] = {-1, 0, 1, 0};
        int dc[] = {0, 1, 0, -1};
        // Start Dijkstra's
        dist[0][0] = 0;
        pq.push({0, {0,0}});
        while(!pq.empty()) {
            auto it = pq.top();
            pq.pop();
            int diff = it.first;
            int row = it.second.first;
            int col = it.second.second;
            // coz whenever we get our destination in priority queue, it will be minimum already
            // So just return it.
            if(row == n-1 && col == m-1)
                return diff;
            // Traverse Neighbours.
            for(int i=0; i < 4; i++) {
                int newr = row + dr[i];
                int newc = col + dc[i];
                if(isValid(newr, newc, n, m)) {
                    // We have to choose minimal effort for every path.
                    int currDiff = abs(arr[newr][newc] - arr[row][col]);
                    int newEffort = max(diff, currDiff);
                    if(newEffort < dist[newr][newc]) {
                        dist[newr][newc] = newEffort;
                        pq.push({dist[newr][newc], {newr, newc}});
                    }
                }
            }
        }
        return 0;
    }
};

