                // This is the first time I'm coming to this node
                // with this short distance
                if(dis + edW < dist[adjNode]) {
                    dist[adjNode] = dis + edW;
                    pq.push({adjNode, dis + edW});
                    ways[adjNode] = ways[node];
                }
                // It is previously visited & we'r visiting again with same distance.
                // Then, just Add the number of ways to reach this point with previous one.
                else if(dis + edW == dist[adjNode]) {
                    ways[adjNode] = (ways[adjNode] + ways[node]) % mod;
                }
            }
        }
        return ways[n-1] % mod;
    }
};

class Solution {
public:
    int dijkstra(int n, vector<pair<int,int>> adj[]) {
        int mod = 1e9 + 7;
        priority_queue<pair<long long, long long>,
            vector<pair<long long, long long>>, greater<pair<long long, long long>>> pq;
        vector<long long> dis(n, 1e15), path(n, 0);
        pq.push({0, 0});                // {dist, Node}
        dis[0] = 0;
        path[0] = 1;
        while (!pq.empty()) {
            long long dist = pq.top().first;
            int node = pq.top().second;
            pq.pop();
            // iterate on its adjacent nodes
            for (auto &child : adj[node]) {
                int adjNode = child.first;
                long long wt = child.second;
                // if it min distance to reach at a node then update it
                if (dist + wt < dis[adjNode]) {
                    dis[adjNode] = dist + wt;
                    path[adjNode] = path[node];
                    pq.push({dist + wt, adjNode});
                }
                else if (dist + wt == dis[adjNode]) {
                    path[adjNode] = (path[node] + path[adjNode]) % mod;
                }
            }
        }
        return path[n - 1];
    }
    int countPaths(int n, vector<vector<int>>& roads) {
        // Matrix into graph
        vector<pair<int,int>> adj[n];
        for(auto &it : roads) {
            int u = it[0];
            int v = it[1];
            int time = it[2];
            adj[u].push_back({v, time});
            adj[v].push_back({u, time});
        }
        return dijkstra(n, adj);
    }
};

