class DisjointSet {
    vector<int> rank, parent, size;
public:
    DisjointSet(int n) {
        rank.resize(n + 1, 0);
        parent.resize(n + 1);
        size.resize(n + 1);
        // Initialize everyone as its parent & size = 1
        for(int i=0; i <= n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }
    int findUPar(int node) {
        // base case
        if(node == parent[node])
            return node;
        // Store its parent while returning.
        return parent[node] = findUPar(parent[node]);
    }
    void unionByRank(int u, int v) {
        int ulp_u = findUPar(u);
        int ulp_v = findUPar(v);
        // Both are already belonging to same component.
        if(ulp_u == ulp_v)
            return ;
        if(rank[ulp_u] < rank[ulp_v]) {
            parent[ulp_u] = ulp_v;      // Connect HigherRank(above) ---->LowerRank(below)
        }
        else if(rank[ulp_u] > rank[ulp_v]){
            parent[ulp_v] = ulp_u;
        }
        // if ranks are equal, attach as per ur wish, but increment the rank of parent.
        else {
            parent[ulp_v] = ulp_u;
            rank[ulp_u]++;
        }
    }
    void unionBySize(int u, int v) {
        int ulp_u = findUPar(u);
        int ulp_v = findUPar(v);
        if (ulp_u == ulp_v)
            return;
        if (size[ulp_u] < size[ulp_v]) {
            parent[ulp_u] = ulp_v;
            size[ulp_v] += size[ulp_u];
        }
        else {
            parent[ulp_v] = ulp_u;
            size[ulp_u] += size[ulp_v];
        }
    }
};
class Solution
{
    public:
    int spanningTree(int V, vector<vector<int>> adj[])
    {
        // Step 1: Adjacency list into vector having Triplet
        vector<pair<int, pair<int,int>>> edges;
        for(int i=0; i < V; i++) {
            for(auto it : adj[i]) {
                int u = i;
                int v = it[0];
                int wt = it[1];
                edges.push_back({wt, {u, v}});
            }
        }
        // Step 2: sort new vector having triplet
        sort(edges.begin(), edges.end());
        // Step 3: Using Disjoint Set Union, Traverse new sorted array nd check if nodes
        // are the part of same component or MST
        DisjointSet ds(V);
        int mstWt = 0;
        for(auto it : edges) {
            int wt = it.first;
            int u = it.second.first;
            int v = it.second.second;
            // IF both nodes are not the part of MST, Include them
            // And Do a path compression.
            if(ds.findUPar(u) != ds.findUPar(v)) {
                mstWt = mstWt + wt;
                ds.unionBySize(u, v);
            }
        }
        return mstWt;
