/*

    Minimum Spanning tree using Kruskal's Algorithm (using Concept of Disjoint Set Union)



    Make sure u r done with Dijoint Set union data structure before doing this question.





    As given Graph is Bidirectional Graph / Undirected Graph.

    If we add u to v & v to u, it will automatically discard v to u

    while checking if the belong to same component. So Ignore that path.



    Algorithm :



    1.) Convert Adjacency List into vector having triplet {wt, u, v}

    2.) Sort the vector as per weight in ascending order.

    3.) Traverse new sorted array and check if both nodes are not part of MST,

        include them by adding their Weight & attach nodes directly to ultimate parents

        by performing path compression to avoid complexity.



        At last, return MST weight.



*/



class DisjointSet {

    vector<int> rank, parent, size;

public:

    DisjointSet(int n) {

        rank.resize(n + 1, 0);

        parent.resize(n + 1);

        size.resize(n + 1);



        // Initialize everyone as its parent & size = 1

        for(int i=0; i <= n; i++) {

            parent[i] = i;

            size[i] = 1;

        }

    }



    int findUPar(int node) {

        // base case

        if(node == parent[node])

            return node;



        // Store its parent while returning.

        return parent[node] = findUPar(parent[node]);

    }



    void unionByRank(int u, int v) {



        int ulp_u = findUPar(u);

        int ulp_v = findUPar(v);



        // Both are already belonging to same component.

        if(ulp_u == ulp_v)

            return ;



        if(rank[ulp_u] < rank[ulp_v]) {

            parent[ulp_u] = ulp_v;      // Connect HigherRank(above) ---->LowerRank(below)

        }

        else if(rank[ulp_u] > rank[ulp_v]){

            parent[ulp_v] = ulp_u;

        }

        // if ranks are equal, attach as per ur wish, but increment the rank of parent.

        else {

            parent[ulp_v] = ulp_u;

            rank[ulp_u]++;

        }

    }



    void unionBySize(int u, int v) {



        int ulp_u = findUPar(u);

        int ulp_v = findUPar(v);



        if (ulp_u == ulp_v)

            return;



        if (size[ulp_u] < size[ulp_v]) {

            parent[ulp_u] = ulp_v;

            size[ulp_v] += size[ulp_u];

        }

        else {

            parent[ulp_v] = ulp_u;

            size[ulp_u] += size[ulp_v];

        }

    }

};



class Solution

{

    public:

    int spanningTree(int V, vector<vector<int>> adj[])

    {

        // Step 1: Adjacency list into vector having Triplet

        vector<pair<int, pair<int,int>>> edges;

        for(int i=0; i < V; i++) {

            for(auto it : adj[i]) {

                int u = i;

                int v = it[0];

                int wt = it[1];



                edges.push_back({wt, {u, v}});

            }

        }



        // Step 2: sort new vector having triplet

        sort(edges.begin(), edges.end());



        // Step 3: Using Disjoint Set Union, Traverse new sorted array nd check if nodes

        // are the part of same component or MST

        DisjointSet ds(V);

        int mstWt = 0;



        for(auto it : edges) {

            int wt = it.first;

            int u = it.second.first;

            int v = it.second.second;



            // IF both nodes are not the part of MST, Include them

            // And Do a path compression.

            if(ds.findUPar(u) != ds.findUPar(v)) {

                mstWt = mstWt + wt;

                ds.unionBySize(u, v);

            }

        }

        return mstWt;

    }

};

Time Complexity: O(N+E) + O(E logE) + O(E*4α*2)   where N = no. of nodes and E = no. of edges. O(N+E) for extracting edge information from the adjacency list. O(E logE) for sorting the array consists of the edge tuples. Finally, we are using the disjoint set operations inside a loop. The loop will continue to E times. Inside that loop, there are two disjoint set operations like findUPar() and UnionBySize() each taking 4 and so it will result in 4*2. That is why the last term O(E*4*2) is added.

Space Complexity: O(N) + O(N) + O(E) where E = no. of edges and N = no. of nodes. O(E) space is taken by the array that we are using to store the edge information. And in the disjoint set data structure, we are using two N-sized arrays i.e. a parent and a size array (as we are using unionBySize() function otherwise, a rank array of the same size if unionByRank() is used) which result in the first two terms O(N).

