class Solution {
public:
    vector<vector<string>> accountsMerge(vector<vector<string>>& details) {
        int n = details.size();
        DisjointSet ds(n);
        // Step 1:
        unordered_map<string, int> mapMailNode;
        for(int i = 0; i < details.size(); i++) {
            for(int j = 1; j < details[i].size(); j++) {        // coz name start at 1.
                string mail = details[i][j];
                if(mapMailNode.find(mail) == mapMailNode.end()) {
                    mapMailNode[mail] = i;                      // Map it {string, index}
                }
                else {      // If already mapped, connect its index with ultimate parent index.
                    ds.unionByRank(i, mapMailNode[mail]);
                }
            }
        }
        // Now, Strings are mapped with index and if there is overlap, their indexes are
        // connected with their ultimate parents that can be used further to get mails of
        // same parent.
        // Step 2:
        // Therefore, using Their ultimate parent, Make an Adjacency list
        // i.e.
        //     Parent/boss   ->   ____, _____, ____
        //     Parnet/boss   ->  ____, ____
        vector<string> mergedMail[n];
        for(auto it : mapMailNode) {
            string mail = it.first;
            int node = it.second;
            int parent = ds.findUPar(node);
            mergedMail[parent].push_back(mail);
        }
        // Step 3: Create answer in the form of vector<vector<string>> in sorted order of internal list.
        vector<vector<string>> ans;
        for(int i=0; i < n; i++) {
            // if no mapping across any index, just ignore that
            if(mergedMail[i].size() == 0)
                continue;
            // otherwise, sort the list and push into matrix.
            vector<string> temp;
            string parent = details[i][0];
            sort(mergedMail[i].begin(), mergedMail[i].end());
            temp.push_back(parent);
            for(auto it : mergedMail[i]) {
                temp.push_back(it);
            }
            ans.push_back(temp);
        }
        sort(ans.begin(), ans.end());
        return ans;
    }
};

