class DisjointSet {
public:
    vector<int> parent, size, rank;
    DisjointSet(int n) {
        parent.resize(n+1);
        size.resize(n+1);
        rank.resize(n+1, 0);
        for(int i=0; i <= n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }
    int findUPar(int node) {
        // Base case
        if(parent[node] == node)
            return node;
        return parent[node] = findUPar(parent[node]);
    }
    void unionByRank (int u, int v) {
        int ulp_u = findUPar(u);
        int ulp_v = findUPar(v);
        // Base case
        // If both are already part of same component,
        if(ulp_u == ulp_v)
            return ;
        if(rank[ulp_u] > rank[ulp_v]) {
            parent[ulp_v] = ulp_u;
        }
        else if(rank[ulp_u] < rank[ulp_v]) {
            parent[ulp_u] = ulp_v;
        }
        else {
            parent[ulp_u] = ulp_v;
            rank[ulp_v]++;
        }
    }
    void unionBySize (int u, int v) {
        int ulp_u = findUPar(u);
        int ulp_v = findUPar(v);
        // Base case
        // If both are already part of same component,
        if(ulp_u == ulp_v)
            return ;
        if(size[ulp_u] > size[ulp_v]) {
            parent[ulp_v] = ulp_u;
            size[ulp_u] += size[ulp_v];
        }
        else {
            parent[ulp_u] = ulp_v;
            size[ulp_v] += size[ulp_u];
        }
    }
};
class Solution {
  public:
    bool isValid(int newr, int newc, int n, int m) {
        return newr >= 0 && newr < n && newc >= 0 && newc < m;
    }
    vector<int> numOfIslands(int n, int m, vector<vector<int>> &operators) {
        int totalNode = n * m;
        DisjointSet ds(totalNode);
        int vis[n][m];
        memset(vis, 0, sizeof(vis));
        vector<int> ans;
        int cnt = 0;
        for(auto it : operators) {
            int row = it[0];
            int col = it[1];
            // If there is already an island, no need to traverse again, so just push count.
            if(vis[row][col] == 1) {
                ans.push_back(cnt);
                continue;
            }
            // Otherwise, make (row, col) island & count totalConnected Islands
            // Count it as individual Island and do subtractions by traversing neighbours if there
            // is any island in neigbour & connect it using disjoint Set
            // Use formula i.e.  NodeNumber = (row*m) + col         where 'm' is totalCol.
            // to get any NodeNumber in matrix for union operation
            vis[row][col] = 1;
            cnt++;
            int dr[] = {-1, 0, 1, 0};
            int dc[] = {0, 1, 0, -1};
            for(int i=0; i < 4; i++) {
                int nbrR = row + dr[i];
                int nbrC = col + dc[i];
                if(isValid(nbrR, nbrC, n, m)) {
                    if(vis[nbrR][nbrC] == 1) {              // If it is island
                        int nodeNo =     row * m + col;
                        int adjNodeNo = nbrR * m + nbrC;
                        // Connect them if they are not connected and decrement
                        // island count
                        if(ds.findUPar(nodeNo) != ds.findUPar(adjNodeNo))
                        {
                            cnt--;
                            ds.unionByRank(nodeNo, adjNodeNo);
                        }
                    }
                }
            }
            ans.push_back(cnt);
        }
        return ans;
    }
};

