        return newr >= 0 && newc >= 0 && newr < n && newc < n;
    }
    int largestIsland(vector<vector<int>>& grid) {
        int n = grid.size();
        DisjointSet ds(n*n);
        // Step 1: whenever we find matrix[i][j] = '1', traverse it neighbours & connect
        // it with its nbr connected components.
        for(int row = 0; row < n; row++) {
            for(int col = 0; col < n; col++) {
                if(grid[row][col] == 0)
                    continue;
                int dr[] = {-1, 0, 1, 0};
                int dc[] = {0, 1, 0, -1};
                for(int i=0; i < 4; i++) {
                    int newr = row + dr[i];
                    int newc = col + dc[i];
                    // If '1' in neighbour, connect current with neighbour.
                    if(isValid(newr, newc, n) && grid[newr][newc] == 1) {
                        int nodeNo = row * n + col;
                        int adjNodeNo = newr * n + newc;
                        ds.unionBySize(nodeNo, adjNodeNo);
                    }
                }
            }
        }
        // Step 2:
        int ans = 0;
        for(int row  = 0; row < n; row++) {
            for(int col = 0; col < n; col++) {
                if(grid[row][col] == 1)
                    continue;
                int dr[] = {-1, 0, 1, 0};
                int dc[] = {0, 1, 0, -1};
                set<int> components;
                for(int i = 0; i < 4; i++) {
                    int newr = row + dr[i];
                    int newc = col + dc[i];
                    if(isValid(newr, newc, n) && grid[newr][newc] == 1) {
                        int adjNodeNo = newr * n + newc;
                        int ultimate_parent = ds.findUPar(adjNodeNo);
                        components.insert(ultimate_parent);
                    }
                }
                int sizeTotal = 0;
                for(auto it : components) {
                    sizeTotal = sizeTotal + ds.size[it];
                }
                ans = max(ans, sizeTotal + 1);  // we have to count current '1' also, which we try to change.
            }
        }
        // Step 3: To Handle Edge Case, if matrix[i][j] == '0' is surrounded by all '1' in four directions.
        int totalCells = n*n;
        for(int cell = 0; cell < totalCells; cell++) {
            int ultimateParent = ds.findUPar(cell);
            ans = max(ans, ds.size[ultimateParent]);
        }
        return ans;
    }
};

