public:
    vector<vector<int>> merge(vector<vector<int>>& a) {
        sort(a.begin(), a.end());
        vector<vector<int>> result;
        int start = a[0][0];
        int end = a[0][1];
        // Traverse whole array.
        for(int i=1; i<a.size(); i++){
            // No Overlapping, so just push element and update start & end.
            // Before pushing element, compare with next.
            if(a[i][0] > end){
                result.push_back({start, end});
                start = a[i][0];
                end = a[i][1];
            }
            // If comparison fails with next, update end, and in next iteration
            // pair will be pushed.
            else if(a[i][0] <= end)
            {
                end = max(end, a[i][1]);        // Dry Run for second case to understand this.
            }
        }
        // To Handle 0th Index wala case.
        result.push_back({start, end});
        return result;
    }
};

