// Linked List cycle method

// t.c: O(N)

// s.c: O(1)



class Solution {

public:

    int findDuplicate(vector<int>& nums) {



        int slow = nums[0];

        int fast = nums[0];



        do {

            slow = nums[slow];          // move one step forward

            fast = nums[nums[fast]];    // move two steps forward

        } while(slow != fast);



        fast = nums[0];



        // Again start moving one step every time for both pointers

        while(slow != fast) {

            slow = nums[slow];

            fast = nums[fast];

        }

        // Once they meet, just either slow or fast.

        return fast;

    }

};

