class Solution {
public:
    double myPow(double x, int n) {
        double ans = 1.0;
        long power = n;
        // Converting Power into Positive power
        if(power < 0)  power = -1*power;
        while(power > 0){
            // If Even power is given, then solve it by dividing power by 2
            // If power is even, Double the answer and Half the power.
            if(power%2 == 0){
                x = x*x;
                power = power/2;
            }
            else{
                ans = ans*x;
                power--;
            }
        }
        // If given power was negative.
        if(n < 0)
        {
            ans = (double)(1.0) / (double)(ans);
        }
        return ans;
    }
};

