/*

If even power is given, 2^4, then it can be written as 2^2  *  2^2

If odd power is given, 2^5, then it can be written as 2 * (2^2  *  2^2)



Even power case can be solved be dividing power into half and multiplying number to itself

But for Odd, we have to Multiply 'n' times as in Brute force.







e.g.                    DRY RUN.

    x = 2, power = 8



    double ans = 1.0

    for power = 8;  x = 2*2 = 4;        power = 8/2 = 4;    ans = 1.0

    for power = 4;  x = 4*4 = 16;       power = 4/2 = 2;    ans = 1.0

    for power = 2;  x = 16*16 = 256;    power = 2/2 = 1;    ans = 1.0

    for power = 1;  ans = 1.0 *x   ;    power-- i.e. power = 0,

                                                        ans = 256,

*/

// Time Complexity: O(log N)

// Space: O(1)

class Solution {

public:

    double myPow(double x, int n) {



        double ans = 1.0;

        long power = n;

        // Converting Power into Positive power

        if(power < 0)  power = -1*power;



        while(power > 0){

            // If Even power is given, then solve it by dividing power by 2

            // If power is even, Double the answer and Half the power.

            if(power%2 == 0){

                x = x*x;

                power = power/2;

            }

            else{

                ans = ans*x;

                power--;

            }

        }



        // If given power was negative.

        if(n < 0)

        {

            ans = (double)(1.0) / (double)(ans);

        }

        return ans;

    }

};

