class Solution {
public:
    int majorityElement(vector<int>& nums) {
        int n = nums.size();
        int element;
        int cnt = 0;
        // Apply Moore's Voting Algorithm.
        for(int i=0; i < nums.size(); i++) {
            if(cnt == 0) {
                element = nums[i];
                cnt = 1;
            }
            else if(nums[i] == element) cnt++;
            else                        cnt--;
        }
        // Checking if Selected element is in majority or not.
        // This case is optional in this question. u can directly return element.
        int freq = 0;
        for(auto it:nums) {
            if(it == element)
                freq++;
        }
        return freq > (n/2) ? element : -1;
    }
};

