public:
    vector<int> twoSum(vector<int>& nums, int target) {
        vector<int> ans;
        int first, second;
        unordered_map<int,int> mp;
        for(int i=0; i < nums.size(); i++) {
            int tar = target - nums[i];
            if(mp.find(tar) != mp.end()) {
                first = i;
                second = mp[tar];
                ans.push_back(min(first, second));
                ans.push_back(max(first, second));
            }
            else    mp[nums[i]] = i;
        }
        return ans;
    }
};

