class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        unordered_map<int, bool> present, checked;
        // Step 1:
        for(auto it:nums)   present[it] = true;
        // Step 2: Traverse array and get starting element of the array to count
        // length of sequence.
        int longest_consecutive = 0;
        for(auto num : nums) {
            // If it is the starting element
            if(!checked[num] && !present[num-1]) {
                int start = num;
                int current_chain = 0;
                while(present[start] == true) {
                    current_chain++;
                    checked[start] = true;
                    start++;
                }
                longest_consecutive = max(longest_consecutive, current_chain);
            }
        }
        return longest_consecutive;
    }
};

