class Solution{
    public:
    int maxLen(vector<int>&A, int n)
    {
        int sum = 0;
        int max_len = 0;
        unordered_map<int,int> prefixSumIndex;
        for(int i=0; i < n; i++) {
            sum += A[i];
            if(sum == 0)    max_len = i+1;
            else {
                // If we found this sum earlier, then get length.
                if(prefixSumIndex.count(sum)) {
                    int curr = i;
                    int prevIdx = prefixSumIndex[sum];
                    max_len = max(max_len, curr-prevIdx);
                }
                // otherwise, store prefixSum with its index, to calculate further.
                else {
                    prefixSumIndex[sum] = i;
                }
            }
        }
        return max_len;
    }
};

