int Solution::solve(vector<int> &A, int k) {
    unordered_map<int,int> mp;
    int prefix_xor = 0;
    int ans = 0;
    for(auto it: A) {
        prefix_xor = prefix_xor ^ it;
        if(prefix_xor == k)
            ans++;
        int remaining = prefix_xor ^ k;
        if(mp.count(remaining))
            ans += mp[remaining];
        mp[prefix_xor]++;
    }
    return ans;
}

