int slidingWindow(string s) {
    int i=0, j=0, ans = 0;
    unordered_map<char, int> mp;
    while(j < s.size()) {
        mp[s[j]]++;
        // mp.size() denotes number of Unique characters
        if(mp.size() == j-i+1) {
            ans = max(ans, j-i+1);
            j++;
        }
        // means koi character repeat ho rha window ch
        else if(mp.size() < j-i+1) {
            while(mp.size() < j-i+1) {
                mp[s[i]]--;
                if(mp[s[i]] == 0)
                    mp.erase(s[i]);
                i++;
            }
            j++;
        }
    }
    return ans;
}

class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        int i=0, j=0, ans = 0;
        set<char> st;
        while(j < s.size()) {
            // If Char is already present then remove char from starting.
            if(st.count(s[j])) {
                st.erase(s[i]);
                i++;
            }
            // If Not present means, all characters are unique
            else {
                st.insert(s[j]);
                ans = max(ans, (int)st.size());
                j++;
            }
        }
        return ans;
    }
