class Solution {
public:
    Node* cloneList(Node* head) {
        Node* dummy = new Node(-1);
        Node* newHead = dummy;
        while(head)
        {
            newHead->next = new Node(head->val);
            newHead = newHead->next;
            head = head->next;
        }return dummy->next;
    }
    Node* copyRandomList(Node* head) {
        // step 1: create a clone list
        Node* cloneHead = cloneList(head);
        // step 2: add cloneNodes in between Original List
        Node* cloneNode = cloneHead;
        Node* originalNode = head;
        while(originalNode && cloneNode)
        {
            Node* forward = originalNode->next;
            originalNode->next = cloneNode;
            originalNode = forward;
            Node* nextt = cloneNode->next;       // do same for clone too.
            cloneNode->next = originalNode;
            cloneNode = nextt;
        }
        // step 3: Copy Random Pointer
        cloneNode = cloneHead;
        originalNode = head;
        while(originalNode)
        {
            Node* clone = originalNode->next;
            // don't add else condition, coz everyNode don't have random.
            if(originalNode->random != NULL)
                clone->random = originalNode->random->next;
            originalNode = originalNode->next->next;
        }
        // step 4: Revert Changes done in step2
        Node* original = head;
        Node* clone = cloneHead;
        /*
            BELOW STATEMENTS CAN BE WRITTEN AS...
            if(original->next !- NULL)  original->next = original->next->next;
            else                        original->next = NULL;
            same for clone node.
        */
        while(original && clone)
        {
            original->next =
                original->next ? original->next->next : original->next;
            clone->next =
                clone->next ? clone->next->next : clone->next;
            original = original->next;
            clone = clone->next;
        }
        return cloneHead;
    }
};

