class Solution{
    public:
    //Function to find the minimum number of platforms required at the
    //railway station such that no train waits.
    int findPlatform(int arr[], int dep[], int n)
    {
      // step 1: Sort both arrival and departure of trains, coz it doesn't matter
      // which train's arrival/departure time is, we just want the number of platforms
      sort(arr, arr+n);
      sort(dep, dep+n);
      // Step 2: Use Two Pointer approach to get maximum platforms used at a time
      int i = 1, j = 0;       // 'i' for arrival, 'j' for departure
      int plateform_needed = 1;
      int result = 1;
      while(i < n && j < n) {
          // If arrival of current if less or equal than previous departure, land it to new
          // platform
          if(arr[i] <= dep[j]) {
              plateform_needed++;
              i++;
          }
          // if arrival of current is greater than departure of previous,
    // we don't need extra platform
          // so, reduce the number of maximum platforms needed.
          // the reason being, we have already initialised plateform_needed = 1
    // before starting the loop.
          else if(dep[j] < arr[i]) {
              plateform_needed--;
              j++;
          }
          result = max(result, plateform_needed);
      }
      return result;
    }
};

