class Solution
{
    public:
    bool static comparison(Job a, Job b)
    {
        return (a.profit > b.profit);
    }
    vector<int> JobScheduling(Job arr[], int n)
    {
        // Step 1: Sort Jobs according to the descending order of profit.
        sort(arr, arr+n, comparison);
        // Step 2: Find Maximum deadline and make an array of that deadline.
        int max_deadline = -1;
        for(int i=0; i < n; i++)
            max_deadline = max(max_deadline, arr[i].dead);
        vector<int> jobs(max_deadline + 1, -1);
        // Step 3: Traverse sorted array and get the slot of job as per available
        // slots in 'jobs' array.
        // Job with the largest deadline should be at last.
        int total_jobs = 0;
        int total_profit = 0;
        for(int i = 0; i < n; i++)
        {
            int deadline = arr[i].dead;
            int curr_profit = arr[i].profit;
            for(int j = deadline; j > 0; j--) {         // coz we are using 1-based indexing.
            // If a Job slot is available.
                if(jobs[j] == -1) {
                    jobs[j] = i;
                    total_jobs++;
                    total_profit += curr_profit;
                    break;
                }
            }
        }
        return {total_jobs, total_profit};
    }
};

