class Solution
{
    public:
    static bool cmp(Item a, Item b) {
        double first = (double)a.value / (double)a.weight;
        double second = (double)b.value / (double)b.weight;
        return first > second;
    }
    double fractionalKnapsack(int W, Item arr[], int n)
    {
        // step 1: Sort according to the value per weight.
        sort(arr, arr+n, cmp);
        double result = 0;
        double maxCapacity = 0;
        for(int i = 0; i < n; i++) {
            double currWt = arr[i].weight;
            double currVal = arr[i].value;
            if(currWt + maxCapacity <= W) {
                result += currVal;
                maxCapacity += currWt;
            }
            // Otherwise, get fractional values of remaining weight.
            else {
                int remain = W - maxCapacity;
                result += ((double)currVal / (double)currWt) * (double)remain;
                break;
            }
        }
        return result;
    }
};

