class Solution{
    public:
    bool isValid(int r, int c, int row, int col) {
        return r >= 0 and r < row and c >= 0 and c < col;
    }
    void solve(int r, int c, int row, int col, string output, vector<string> &final,
                vector<vector<int>> &vis, vector<vector<int>> &grid)
    {
        // Base case
        if(!isValid(r, c, row, col) or grid[r][c] == 0 or vis[r][c] == 1)
            return ;
        if(r == row-1 and c == col-1) {
            final.push_back(output);
            return ;
        }
        vis[r][c] = 1;
        solve(r+1, c, row, col, output + 'D', final, vis, grid);    // Down
        solve(r-1, c, row, col, output + 'U', final, vis, grid);    // UP
        solve(r, c+1, row, col, output + 'R', final, vis, grid);    // Right
        solve(r, c-1, row, col, output + 'L', final, vis, grid);    // Left
        vis[r][c] = 0;
    }
    vector<string> findPath(vector<vector<int>> &m, int n) {
        if(m[0][0] == 0)    return {};
        string output = "";
        vector<string> final;
        vector<vector<int>> vis(n, vector<int> (n, 0));
        solve(0, 0, n, n, output, final, vis, m);
        return final;
    }
};

