class Solution {
public:
    bool isSafe(int row, int col, char val, vector<vector<char>> &arr) {
        for(int i=0; i < 9; i++) {
            // Col Check -> Col remain same
            if(i != row and arr[i][col] == val)
                return false;
            // Row Check -> Row remain same
            if(i != col and arr[row][i] == val)
                return false;
            // 3 x 3 Matrix check
            // To understand this learn this formula
            // row = 3 * (row/3) + i/3
            // col = 3 * (col/3) + i%3
            int r = 3*(row/3) + i/3;
            int c = 3*(col/3) + i%3;
            if(row != r and col != c and arr[r][c] == val)
                return false;
        }
        return true;
    }
    bool isValidSudoku(vector<vector<char>>& board) {
        for(int i=0; i < 9; i++) {
            for(int j=0; j < 9; j++) {
                if(board[i][j] != '.') {
                    char val = board[i][j];
                    if(!isSafe(i, j, val, board))
                        return false;
                }
            }
        }
        return true;
    }
};

