class Solution {
public:
    bool is_safe_to_put(int row, int col, vector<string> board, int n) {
        int given_row = row;
        int given_col = col;
        // Left Upper Diagonal Check (row and col are variable)
        while(row >= 0 and col >= 0) {
            if(board[row][col] == 'Q')
                return false;
            row--;
            col--;
        }
        // Left Straight Check (column is variable)
        row = given_row;
        col = given_col;
        while(col >= 0) {
            if(board[row][col] == 'Q')
                return false;
            col--;
        }
        // Left Lower Diagonal Check (row and col are variable)
        row = given_row;
        col = given_col;
        while(row < n and col >= 0) {
            if(board[row][col] == 'Q')
                return false;
            row++;
            col--;
        }
        return true;
    }
    void solve(int col, int n, vector<string> &board, vector<vector<string>> &ans) {
        // When we reached last column, means 1 Grid is ready so take it.
        if(col == n) {
            ans.push_back(board);
            return ;
        }
        // To put Queen at Current COL, Try to check at every row.
        // If it is possible to put, then put it and recursive call,
        // Otherwise, Omit it from it Selected position, means,
        // Yan te answer possible nhi h
        // or yan fr answer mill gya hai aur store kr leya hai aapan.
        for(int row = 0; row < n; row++) {
            if(is_safe_to_put(row, col, board,  n)) {
                board[row][col] = 'Q';
                solve(col+1, n, board, ans); // Go to next col and again try all rows
                board[row][col] = '.';
            }
        }
    }
    vector<vector<string>> solveNQueens(int n) {
        vector<vector<string>> ans;
        vector<string> board(n);
        string emptyStr(n, '.');       // Create Dotted String/Empty String.
        for(int i=0; i < n; i++) {
            board[i] = emptyStr;     // Making empty grid using 1-D vector and string.
        }
        solve(0, n, board, ans);
        return ans;
    }
};

class Solution {
public:
    void solve(int col, int n, vector<string> &grid, vector<vector<string>> &ans,
              vector<int> &rowCheck, vector<int> &lowerDiagonal, vector<int> &upperDiagonal) {
        // Base case
        if(col == n) {
            ans.push_back(grid);
            return ;
        }
        for(int row=0; row < n; row++) {
            if(rowCheck[row] == 0 and lowerDiagonal[row+col] == 0 and
              upperDiagonal[n-1 + col-row] == 0) {
                rowCheck[row] == 1;
                lowerDiagonal[row+col] == 1;        // for lowerDiagonal, (row + col)
                upperDiagonal[n-1 + col-row] == 1;  // for UpperDiagonal, ([n-1] + [col-row])
                solve(col+1, n, grid, ans, rowCheck, lowerDiagonal, upperDiagonal);
                rowCheck[row] == 0;
                lowerDiagonal[row+col] == 0;
                upperDiagonal[n-1 + col-row] == 0;
            }
        }
    }
    vector<vector<string>> solveNQueens(int n)
    {
        // Step 1: Grid Making
        vector<vector<string>> ans;
        vector<string> grid(n);
        string s(n, '.');
        for(int i=0; i < n; i++)
            grid[i] = s;
        // Step 2:
        vector<int> rowCheck(n, 0);
        vector<int> lowerDiagonal(2*n-1, 0);    // diagonals start from top of the col
        vector<int> upperDiagonal(2*n-1, 0);    // diagonals start from bottom of the col
        solve(0, n, grid, ans, rowCheck, lowerDiagonal, upperDiagonal);
        return ans;
    }
};

