Time Complexity: Exponential in nature since we are trying out all ways, 

to be precise it is O(N! * N).

Space Complexity: O(N)













// SOLUTIONN 2:

// How to Optimise time using extra Space

// Use Extra Space of Unordered_map or Vector as Map.

// To get Know if there is Queen at this row.





For Row check       - Simply check if rowChec[row] = 1, means Queen present

For Lower Diagonal  - Check if lowerDiagonal[row + col] = 1, means Queen present.

For Upper Diagonal  - Check if upperDiagonal[n-1 + col - row] = 1, means Queen present.









class Solution {

public:

    void solve(int col, int n, vector<string> &grid, vector<vector<string>> &ans,

              vector<int> &rowCheck, vector<int> &lowerDiagonal, vector<int> &upperDiagonal) {

        // Base case

        if(col == n) {

            ans.push_back(grid);

            return ;

        }



        for(int row=0; row < n; row++) {



            if(rowCheck[row] == 0 and lowerDiagonal[row+col] == 0 and

              upperDiagonal[n-1 + col-row] == 0) {



                rowCheck[row] == 1;

                lowerDiagonal[row+col] == 1;        // for lowerDiagonal, (row + col)

                upperDiagonal[n-1 + col-row] == 1;  // for UpperDiagonal, ([n-1] + [col-row])



                solve(col+1, n, grid, ans, rowCheck, lowerDiagonal, upperDiagonal);



                rowCheck[row] == 0;

                lowerDiagonal[row+col] == 0;

                upperDiagonal[n-1 + col-row] == 0;

            }

        }

    }



    vector<vector<string>> solveNQueens(int n)

    {

        // Step 1: Grid Making

        vector<vector<string>> ans;

        vector<string> grid(n);

        string s(n, '.');



        for(int i=0; i < n; i++)

            grid[i] = s;





        // Step 2:

        vector<int> rowCheck(n, 0);

        vector<int> lowerDiagonal(2*n-1, 0);    // diagonals start from top of the col

        vector<int> upperDiagonal(2*n-1, 0);    // diagonals start from bottom of the col



        solve(0, n, grid, ans, rowCheck, lowerDiagonal, upperDiagonal);



        return ans;

    }

};

