public:
    int getFirstPosition(vector<int> &arr, int target){
        int start = 0;
        int end = arr.size()-1;
        int mid = start +(end-start)/2;
        int first = -1;
        while(start <= end){
            if(arr[mid] == target){
                first = mid;
                end = mid-1;
            }
            else if(arr[mid] < target){
                start = mid+1;
            }
            else if(arr[mid] > target){
                end = mid-1;
            }
            //Update mid everytime
            mid = start +(end-start)/2;
        }
        return first;      //If not found
    }
    int getLastPosition(vector<int> &arr, int target){
        int start = 0;
        int end = arr.size()-1;
        int mid = start +(end-start)/2;
        int last = -1;
        while(start <= end){
            if(arr[mid] == target){
                last = mid;
                start = mid+1;
            }
            else if(arr[mid] < target){
                start = mid+1;
            }
            else if(arr[mid] > target){
                end = mid-1;
            }
            //Update mid everytime
            mid = start +(end-start)/2;
        }
        return last;      //If not found
    }
