    bool isAscending = arr.get(start) < arr.get(end);       //It is in asceding order if first element is                                                                     less than last element
    while(start <= end){
        int mid = start +(end-start)/2;
        if(arr.get(mid) == target){
            return mid;
        }
        //Ascending Order
        if(isAscending == true){
            if(arr.get(mid) > target){
                end = mid-1;
            }
            else if(arr.get(mid) < target){
                start = mid+1;
            }
        }
        //Descending Order
        else{
            if(arr.get(mid) > target){  // search in right part
                start = mid+1;
            }
            else if(arr.get(mid) < target){     //searcch in left part
                end = mid-1;
            }
        }
    }
    return -1;
}

class Solution {
public:
    int getPeakIndex(MountainArray &arr){
        int start = 0;
