        int ans;
        while(start < end){
            int mid = start +(end-start)/2;
	//there is confusion in if else statement, for better understanding read peak element wala question
            if(arr.get(mid) < arr.get(mid+1)){
                ans = mid;
                start = mid+1;
            }
            else{
                end = mid;
            }
        }
        return ans;
    }
    // For Ascending Order
    int binarySearch(MountainArray &arr, int target, int start, int end){
        while(start <= end){
            int mid = start +(end-start)/2;
            if(arr.get(mid) == target){
                return mid;
            }
            else if(arr.get(mid) < target){     //Search in right part
                start = mid+1;
            }
            else if(arr.get(mid) > target){     //Search in left part
                end = mid-1;
            }
        }
        return -1;
    }
    //For Descending Order
    int reverseBinarySearch(MountainArray &arr, int target, int start, int end){
        while(start <= end){
            int mid = start +(end-start)/2;
            if(arr.get(mid) == target){
                return mid;
            }
            else if(arr.get(mid) < target){     //Search in left part
                end = mid-1;
            }
            else if(arr.get(mid) > target){     //Search in right part
                start = mid+1;
            }
        }
        return -1;
    }
    int findInMountainArray(int target, MountainArray &mountainArr) {
        int peak = getPeakIndex(mountainArr);           //Step 1: Find Peak Index
        // In actual peak element is peak+1, but there will be no problem coz we r finding peak, just
        // to divide array into two halves.
        cout << "Peak element is " << mountainArr.get(peak) << endl;
        int first = binarySearch(mountainArr, target, 0, peak);     //Step 2: Search in Ascending Array of                                                                            mountain/Bitonic array
        if(first != -1){
            return first;
        }                                  //Step 3: If not found, Search in Descending Array
        return reverseBinarySearch(mountainArr,target, peak+1, mountainArr.length()-1);
    }
};

