class Solution {
public:
    void binarySearch(vector<int> nums, int start, int end, int target, vector<int> & ans){
        // Base case
        if(start > end)
            return;
        int mid = start + (end - start)/2;
        // If mid is equal to target, apply Binary Search on both halves of array.
        if(nums[mid] == target){
            binarySearch(nums, start, mid-1, target, ans);
            ans.push_back(mid);
            binarySearch(nums, mid+1, end, target, ans);
        }
        // Search in Right part only
        else if(nums[mid] < target){
            binarySearch(nums, mid+1, end, target, ans);
        }
        // Search in Left Part only
        else{
            binarySearch(nums, start, mid-1, target, ans);
        }
    }
    vector<int> targetIndices(vector<int>& nums, int target) {
        vector<int> ans;
        // Step 1: Sort the array
        sort(nums.begin(), nums.end());
        int start = 0, end = nums.size()-1, mid = start + (end-start)/2;
        // Step 2: Apply Binary Search.
        binarySearch(nums, start, end, target, ans);
        return ans;
    }
};

