bool isPossible(vector<int> arr, int n, int totalStudents, int max_pages_to_each_student) {

    int studentCount = 1;

    int pageSum = 0;



    for(int i = 0; i<n; i++) {

        int currPages = arr[i];



        if(pageSum + currPages <= max_pages_to_each_student) {

            pageSum += currPages;

        }

        else

        {

            studentCount++;

            if(studentCount > totalStudents || currPages > max_pages_to_each_student ) {

                return false;

            }

            pageSum = currPages;   // break the chain.

        }

        if(studentCount > totalStudents) {

            return false;

        }

    }

    return true;

}



int allocateBooks(vector<int> arr, int n, int m) {

    int s = 0;

    int sum = 0;



    for(int i = 0; i<n; i++) {

        sum += arr[i];

    }

    int e = sum;

    int ans = -1;

    int mid = s + (e-s)/2;



    while(s<=e)

    {

        // IF this much number of pages can be allocated among m students.

        // store this answer and find minimum as well.

        if(isPossible(arr,n,m,mid)) {

            ans = mid;

            e = mid - 1;

        }

        else {

            s = mid + 1;

        }

        mid = s + (e-s)/2;

    }

    return ans;

}

