typedef pair<int,int> pp;
class Solution {
public:
    vector<vector<int>> kSmallestPairs(vector<int>& nums1, vector<int>& nums2, int k) {
        priority_queue<pp, vector<pp>, greater<pp>> q;
        // Step 1: Push {num1[i] + nums2[0], 0} in queue.
        // Push all possible pairs with first element of second array and the
        // entire first array
        for(auto num1 : nums1) {
            int sum = num1 + nums2[0];
            q.push({sum, 0});
        }
        // Step 2: While popping out the element, push (pos+1) element as well
        vector<vector<int>> ans;
        while(q.size() && k--)
        {
            int sum = q.top().first;
            int pos = q.top().second;
            q.pop();
            int firstNum = sum - nums2[pos];
            int secondNum = nums2[pos];
            ans.push_back({firstNum, secondNum});
            // Push new element into queue i.e. nums2[pos+1]
            if(pos + 1 < nums2.size())
            {
                int first = sum-nums2[pos];
                int second = nums2[pos+1];
                int newSum = first + second;
                q.push({newSum, pos+1});
            }
        }
        return ans;
    }
};

