class Solution {
public:
    long long totalCost(vector<int>& costs, int k, int mxAllowed) {
        // Step 1: use two Min Heaps.
        priority_queue<int, vector<int>, greater<int>> first, second;
        // Step 2: Push 'mxAllowed' number of workers in q1 and q2 each.
        // Step 3: Pick and Pop
        int start = 0;
        int end = costs.size()-1;
        long long result = 0;
        while(k) {
		// Hands-on Push required number of elements into queue.
            while(first.size() != mxAllowed && start <= end)    first.push(costs[start++]);
            while(second.size() != mxAllowed && end >= start)   second.push(costs[end--]);
            int top1 = first.size() > 0 ? first.top() : INT_MAX;
            int top2 = second.size()> 0 ? second.top(): INT_MAX;
            if(top1 <= top2) {
                result += top1;
                first.pop();
            }
            else {
                result += top2;
                second.pop();
            }
            k--;
        }
        return result;
    }
};

