class heap{
public:
    int arr[1000];
    int size;
    heap() {
        size = 0;
        arr[0] = -1;    // coz heap will start from first index
    }
    void insertNode(int element) {
        // Step 1: Insert Node at the end of heap
        size++;
        int index = size;
        arr[index] = element;
        // Step 2: Keep swapping the newNode to its parent, until it
        // reaches it correct position
        while(index > 1) {
            int parent = index/2;
            if(arr[parent] < arr[index]){
                swap(arr[parent], arr[index]);
                index = parent;
            }
            else    return ;
        }
    }
    // Always delete first/ top element of the heap
    void deleteNodeFromHeap() {
        if(size == 0) {
            cout << "Nothing to delete from heap " << endl;
            return ;
        }
        // Step 1: Copy last Node at the root, coz after deletion, there should be
        // a node at the place of deleted node, so we copied the last one.
        arr[1] = arr[size];
        size--;
        // Step 2: Propagate the newRoot to its correct position
        int index = 1;
        while(index < size) {
            int leftChild = 2*index;
            int rightChild = 2*index+1;
            if(leftChild < size && arr[leftChild] > arr[index]) {
                swap(arr[index], arr[leftChild]);
                index = leftChild;
            }
            else if(rightChild < size && arr[rightChild] > arr[index]) {
                swap(arr[index], arr[rightChild]);
                index = rightChild;
            }
            else    return ;
        }
    }
    void printHeap() {
        for(int i = 1; i <= size; i++)
            cout << arr[i] << ", ";
        cout << endl;
    }
};
