using namespace std;
class Stack{
    public:
    //Properties or data members
        int *arr;
        int size;
        int top;
    //Behaviour
    //constructor
    Stack(int sIZE){
        this -> size = sIZE;
        arr = new int[sIZE];
        top = -1;
    }
    void push(int element) {
        if(size - top > 1){		//Means we need atleast 1 space to insert an element
            top++;
            arr[top] = element;
        }
        else{
            cout << "Stack overflow" << endl;
        }
    }
    void pop() {
        if(top >= 0){
            top--;
        }
        else{
            cout << "Stack underflow " << endl;
        }
    }
    int peek() {
        if(top >= 0){
            return arr[top];
        }
        return -1;
    }
    bool isEmpty() {
        if(top == -1){
            return true;
        }
        else{
            return false;
        }
    }
};
