public:
        queue<int> q1;
        queue<int> q2;
    MyStack() {
    }
    void push(int x) {
        //Step 1: Pop the element until q1 becomes empty
        // and push these to second queue
        while(!q1.empty()){
            q2.push(q1.front());
            q1.pop();
        }
        //Step 2: Push the given element to q1
        q1.push(x);
        //Step 3: Transfer all the elements from q2 to q1.
        //Pushed element will be automatically at the top of q1
        while(!q2.empty()){
            q1.push(q2.front());
            q2.pop();
        }
    }
    int pop() {
        int value = q1.front();
        q1.pop();
        return value;
    }
    int top() {
        return q1.front();
    }
    bool empty() {
        return q1.empty();
    }
};

