        //Step 1: push the given element to the queue
        q.push(x);
        //Step 2: Iterate till the TotalSize - 1 and push the front elements again
        // to the queue so that all elements will be at top and it
        // will follow LIFO order which is property of the stack
        for(int i=0; i < q.size()-1; i++){
            q.push(q.front());
            q.pop();
        }
    }
    int pop() {
        int value = q.front();
        q.pop();
        return value;
    }
