class MyQueue {
public:
    stack<int> input;
    stack<int> output;
    MyQueue() {
        input = stack<int> ();
        output = stack<int> ();
    }
    // Push the given Number to input
    void push(int x) {
        input.push(x);
    }
    int pop() {
        //If output is empty
        if(output.empty()){
            //Transferring input to output
            while(!input.empty()){
                output.push(input.top());
                input.pop();
            }
        }
        //else
        int value = output.top();
        output.pop();
        return value;
    }
    int peek() {
        //If output is empty
        if(output.empty()){
            while(!input.empty()){
                output.push(input.top());
                input.pop();
            }
        }
       // then
        return output.top();
    }
    bool empty() {
        return output.empty() && input.empty();
    }
};

