class LRUCache {
public:
    class node{
    public:
        int key;
        int val;
        node* next;
        node* prev;
        node(int keyy, int value) {
            this->key = keyy;
            this->val = value;
        }
    };
    node* head = new node(-1, -1);
    node* tail = new node(-1, -1);
    int cap;
    unordered_map<int, node*> mp;
    LRUCache(int capacity) {
        cap = capacity;
        head->next = tail;
        tail->prev = head;
    }
    void deleteNode(node* nodeToDel) {
        // To reduce complexity of code
        node* delPrev = nodeToDel -> prev;
        node* delNext = nodeToDel -> next;
        delPrev -> next = delNext;
        delNext -> prev = delPrev;
    }
    void insertNode(node* newNode) {
        node* temp = head -> next;
        newNode -> next = temp;
        newNode -> prev = head;
        head -> next = newNode;
        temp -> prev = newNode;
    }
    int get(int key) {
        if(mp.find(key) != mp.end()) {
            node* resNode = mp[key];
            int result = resNode->val;
            // Remove from least recently used and add it to most recently used.
            // i.e. head->next vala portion.
            mp.erase(key);
            deleteNode(resNode);
            insertNode(resNode);
            mp[key] = head->next;
            return result;
        }
        return -1;
    }
    void put(int key, int value) {
        if(mp.find(key) != mp.end()) {
            node* existingNode = mp[key];
            mp.erase(key);
            deleteNode(existingNode);
        }
        // If size exceeds capacity, remove least recently used node.
        if(mp.size() == cap) {
            node* nodeToDel = tail->prev;
            mp.erase(tail -> prev -> key);
            deleteNode(nodeToDel);
        }
        node* newNode = new node(key, value);
        insertNode(newNode);
        mp[key] = head->next;
    }
};

