class Solution {
public:
    //This function will return index of Next smaller number but not it's value
    vector<int> nextSmallerElement(vector<int> &arr){
        // Pair (NSR_element, NSR_index)
        stack<int> s;
        vector<int> NSR;
        for(int i=arr.size()-1; i>=0; i--){
            int curr = arr[i];
            while(!s.empty() && arr[s.top()] >= curr){
                s.pop();
            }
            if(s.size() == 0){
                NSR.push_back(-1);
            }
            else if(s.size() !=0 && arr[s.top()] < curr){
                NSR.push_back(s.top());
            }
            s.push(i);
        }
        reverse(NSR.begin(), NSR.end());
        return NSR;
    }
    //This function gives the nearest Smaller to left element's index but not it's value
    vector<int> previousSmallerElement(vector<int> &arr){
        // Pair (NSL_element, NSL_index)
        stack<int> s;
        vector<int> NSL;
        for(int i=0; i<arr.size(); i++){
            int curr = arr[i];
            while(!s.empty() && arr[s.top()] >= curr){
                s.pop();
            }
            if(s.size() == 0){
                NSL.push_back(-1);
            }
            else if(s.size() !=0 && arr[s.top()] < curr){
                NSL.push_back(s.top());
            }
            s.push(i);
        }
        return NSL;
    }
    int largestRectangleArea(vector<int>& heights) {
            //Step 1: Calculate next smaller element's index
            vector<int> next = nextSmallerElement(heights);
            //Step 2: Calculate previous smaller element's index
            vector<int> previous = previousSmallerElement(heights);
        //Now, we have found next and previous smaller element's index
        //These two will be our boundaries to calculate area at last
        // i.e. length = nextSmallerIndex - prevSmallerIndex - 1, breadth = height[i]
            int area = INT_MIN;
            for(int i=0; i<heights.size(); i++){
                int length = heights[i];
                //means we got next element out of the vector i.e. last index or total size of vector
                if(next[i] == -1){
                    next[i] = heights.size();
                }
                int breadth = next[i] - previous[i] - 1;
                int new_area = length*breadth;
                area = max(area, new_area);
            }
        return area;
    }
};

