class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& arr, int k) {
        deque<int> q;
        int i=0;
        int j=0;
        vector<int> ans;
        while(j < arr.size()) {
    // Keep removing element less than current.
            while(q.size() > 0 && q.back() < arr[j])
                q.pop_back();
            q.push_back(arr[j]);
            if(j-i+1 < k)           j++;
            else if(j-i+1 == k) {
                ans.push_back(q.front());
                // Slide window
                if(arr[i] == q.front())
                    q.pop_front();
                i++;
                j++;
            }
        }
        return ans;
    }
};

