class MinStack {
public:
    stack<long long int> s;
    long long int min;
    MinStack() {
    }
    void push(int val) {
        //First element to push or Stack is empty
        if(s.size() == 0){
            s.push(val);
            min = val;
            return ;
        }
        //Means we r pushing Greater value, so no need to update min
        else if(val >= min){
            s.push(val);
        }
        //Means we are pushing smaller value than min, so update min
        // But push the corrupted value of given number or consider it as flag
        // 2 * x - miniElement ---- How to convert original value into flag or corrupted value
        else if(val < min){
            s.push((long long)2*val - min);
            min = val;
        }
    }
    void pop() {
        //If top element is greater or equal to the min, no need to update min
        if(s.top() >= min){
            s.pop();
        }
        //Otherwise, we have to update the min value
        // 2* miniElement - x ---- How to convert the corrupted value into
        // original and update that value to min
        else{
            min = (long long)2 * min - s.top();
            s.pop();
        }
    }
    int top() {
        //If Stack is empty
        if(s.size() == 0){
            return -1;
        }
        // If value is greater, no need to update min just return top
        else if(s.top() >= min){
            return s.top();
        }
        //If top value is smaller means that value is corrupted value,
        // Its original value will be in miniElement
        // So, return miniElement
        else{
            return min;
        }
    }
    int getMin() {
        if(s.size() == 0){
            return -1;
        }
        return min;
    }
};

