class Solution {
public:
    string reverseWords(string s) {
        vector<string> arr;
        int i = 0;
        while(i < s.size()) {
            int j = i;
            string str = "";
            // Pick words
            while(j < s.size() and s[j] != ' ') {
                str.push_back(s[j]);
                j++;
            }
            i = j+1;
            if(str.size())
                arr.push_back(str);
        }
        reverse(arr.begin(), arr.end());
        string result = "";
        for(auto it:arr) {
            result += it + ' ';
        }
        result.pop_back();
        return result;
    }
};

