class Solution {
public:
    int get_count_at_each_level(TreeNode* root) {
        int ans = 0;
        queue<pair<TreeNode*, unsigned long long int>> q;
        // ParentIndex = it.second;     talking about in queue.
        // leftIndex for curr =  2*parentIndex + 1
        // rightIndex for curr = 2*parentIndex + 2
        q.push({root, 0});
        while(q.size()) {
            unsigned long long int sz = q.size();
            unsigned long long int leftIdx = q.front().second;     // first node di second Val.
            unsigned long long int rightIdx = 0;
            for(int i=0; i < sz; i++)
            {
                auto it = q.front();
                TreeNode* curr = it.first;
                unsigned long long int parentIdx = it.second;
                rightIdx = parentIdx;
                q.pop();
                if(curr->left) {
                    // push it with its new Index corresponding to Parent
                    q.push({curr->left, 2*parentIdx + 1});
                }
                if(curr->right) {
                    // push it with its new Index corresponding to Parent
                    q.push({curr->right, 2*parentIdx + 2});
                }
            }
            ans = max(ans, int(rightIdx-leftIdx+1));
        }
        return ans;
    }
    int widthOfBinaryTree(TreeNode* root) {
        return get_count_at_each_level(root);
    }
};

