class Solution {
public:
    void flatten(TreeNode* root) {
        TreeNode* curr = root;
        while(curr != NULL){
            if(curr->left != NULL){
                TreeNode* pre = curr->left;
                while(pre->right != NULL)
                    pre = pre->right;
                pre->right = curr->right;
                curr->right = curr->left;   // now, curr->left becomes right, that's why
                                            // we went to curr->right in next calls
