class BSTIterator {
public:
    stack<TreeNode*> st;
    BSTIterator(TreeNode* root) {
        // Push all left elements of root
        leftTree(root);
    }
    int next() {
        // Remember, next() call will always be valid
        // Asnwer will be at the top of stack, store it
        TreeNode* root = st.top();
        st.pop();
        int result = root->val;
        // Push all left Nodes of Right Subtree again.
        root = root->right;
        leftTree(root);
        return result;
    }
    bool hasNext() {
        return st.empty() ? false : true;
    }
    void leftTree(TreeNode* root) {
        while(root) {
            st.push(root);
            root = root->left;
        }
    }
};

