class Solution{
public:
    long maximumSumSubarray(int K, vector<int> &Arr , int N){
        long maxSum = INT_MIN;
        long sum = 0;
        int i=0, j=0;
        while(j < Arr.size())
        {
            // Step 1: Find sum of elements till the window size
            sum += Arr[j];
            // Step 2: Find window of size k
            if(j-i+1 < K){
                j++;
            }
            // Once, we get the sum then update maxSum and maintain size of window
            // by increment next and decrement 0th index's sum
            else if(j-i+1 == K)
            {
                maxSum = max(maxSum, sum);
                sum = sum - Arr[i];
                i++;
                j++;
            }
        }
        return maxSum;
    }
};

