    int search(string pat, string str) {
        int ans = 0;
        //to the count of character of pattern
        unordered_map<char,int> mp;
        for(auto &x : pat)  mp[x]++;
        int distinctCharacters = mp.size();
        int windowSize = pat.size();
        int i=0, j=0;
        while(j < str.size()) {
            // Adding j's elements
            if(mp.find(str[j]) != mp.end()) {
                mp[str[j]]--;
