class Solution
{
  public:
    //Function to find maximum of each subarray of size k.
    vector <int> max_of_subarrays(int *arr, int n, int k)
    {
        vector<int> ans;
        deque<int> q;
        int i=0, j=0;
        while(j < n) {
            // Step 1: Calculaltion
            // Remove all elements less than current.
            // coz we want maximum at front.
            while(q.size() > 0 && q.back() < arr[j])
                q.pop_back();
            q.push_back(arr[j]);
            if(j-i+1 < k) {
                j++;
            }
            else if(j-i+1 == k) {
                // Step 2: Get answer
                ans.push_back(q.front());
                // Step 3: Slide Window and remove calculations.
                if(q.front() == arr[i])
                    q.pop_front();
                i++;
                j++;
            }
        }
        return ans;
    }
};

