class Solution {
public:
    // Two pass solution
    int solve(string str, int k, char ch) {
        int extra = 0;
        int right = 0, left = 0;
        int ans = 0;
        while(right < str.size()) {
            if(str[right] != ch)    extra++;
            if(extra <= k) {
                ans = max(ans, right-left+1);
                right++;
            }
            else {
                while(left < str.size() and extra > k) {
                    if(str[left] != ch) extra--;
                    left++;
                }
                right++;
            }
        }
        return ans;
    }
    // One pass solution (Mine)
    int solve2(string answerKey, int k) {
        int trueCount = 0, falseCount = 0;
        int ans = 0;
        int left = 0, right = 0;
        int sz = answerKey.size();
        while(right < sz) {
            if(answerKey[right] == 'T') trueCount++;
            else                        falseCount++;
            // If both counts becomes greater than 'K',
            // then we can't get consecutive elements by applying
            // 'K' operations.
            if(trueCount > k && falseCount > k) {
                // Start removing from first till we get any count < k
                while(left < sz && trueCount > k && falseCount > k) {
                    if(answerKey[left] == 'T') {
                        trueCount--;
                        left++;
                    }
                    else {
                        falseCount--;
                        left++;
                    }
                }
            }
            ans = max(ans, right-left+1);
            right++;
        }
        return ans;
    }
    int maxConsecutiveAnswers(string answerKey, int k) {
        int sol1 = solve(answerKey, k, 'T');    // solve for 'True'
        int sol2 = solve(answerKey, k, 'F');    // solve for 'False'
        // Two-pass solution
        // return max(sol1, sol2);
        // One-pass solution
        return solve2(answerKey, k);
    }
};

